comms.text:
@1 וּמַלֵיל יְיָ עִם מֹשֶׁה בָּתַר דְמִיתוּ תְּרֵין בְּנֵי אַהֲרֹן בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ וּמִיתוּ:
@2 וַאֲמַר יְיָ לְמֹשֶׁה מַלֵל עִם אַהֲרֹן אָחוּךְ וְלָא יְהֵי עָלֵל בְּכָל עִדָן לְקוּדְשָׁא מִגָיו לְפָרֻכְתָּא לָקֳדָם כַּפֻּרְתָּא דִי עַל אֲרוֹנָא וְלָא יְמוּת אֲרֵי בַּעֲנָנָא אֲנָא מִתְגְלִי עַל בֵּית כַּפֻּרְתָּא:
@3 בְּדָא יְהֵי עָלֵל אַהֲרֹן לְקוּדְשָׁא בְּתוֹר בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא:
@4 כִּתּוּנָא דְבוּצָא קוּדְשָׁא יִלְבָּשׁ וּמִכְנְסִין דְבוּץ יְהוֹן עַל בִּסְרֵהּ וּבְהֶמְיָנָא דְבוּץ יֵסַר וּבְמִצְנֶפְתָּא דְבוּצָא יָחֵת בְּרֵישֵׁהּ לְבוּשֵׁי קוּדְשָׁא אִנוּן וְיַסְחֵי בְמַיָא יָת בִּ:סרֵהּ וְיַלְבְּשִׁנוּן:
@5 וּמִן כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יִסַב תְּרֵין צְפִירֵי עִזִין לְחַטָאתָא וּדְכַר חַד לַעֲלָתָא:
@6 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ:
@7 וְיִסַב יָת תְּרֵין צְפִירִין וִיקִים יָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@8 וְיִתֵּן אַהֲרֹן עַל תְּרֵין צְפִירִין עַדְבִין עַדְבָא חַד לִשְׁמָא דַיְיָ וְעַדְבָא חַד לַעֲזָאזֵל:
@9 וִיקָרֵב אַהֲרֹן יָת צְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לִשְׁמָא דַיְיָ וְיַעְבְּדִנֵהּ חַטָאתָא:
@10 וּצְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לַעֲזָאזֵל יִתָּקַם כַּד חַי קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי לְשַׁלַח יָתֵהּ לַעֲזָאזֵל לְמַדְבְּרָא:
@11 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְיִכּוֹס יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ:
@12 וְיִסַב מְלֵי מַחְתִּיתָא גוּמְרִין דְאֶשָׁא מֵעִלַוֵי מַדְבְּחָא מִן קֳדָם יְיָ וּמְלֵי חָפְנוֹהִי קְטוֹרֶת בּוּסְמִין דַקִיקִין וְיָעֵל מִגָיו לְפָרֻכְתָּא:
@13 וְיִתֵּן יָת קְטוֹרֶת בּוּסְמַיָא עַל אֶשָׁתָא לָקֳדָם יְיָ וְחָפֵי עֲנָנָא קְטָרְתָּא יָת כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא וְלָא יְמוּת:
@14 וְיִסַב מִדְמָא דְתוֹרָא וְיַדֵי בְאֶצְבְּעֵהּ עַל אַפֵּי כַּפּוּרְתָּא קִדוּמָא וְלָקֳדָם כַּפֻּרְתָּא יַדִי שְׁבַע זִמְנִין מִן דְמָא בְּאֶצְבְּעֵהּ:
@15 וְיִכּוֹס יָת צְפִירָא דְחַטָאתָא דִי לְעַמָא וְיָעֵל יָת דְמֵהּ לְמִגָיו לְפָרֻכְתָּא וְיַעְבֵּד לִדְמֵהּ כְּמָא דִי עֲבַּד לִדְמָא דְתוֹרָא וְיַדִי יָתֵהּ עַל כַּפֻּרְתָּא וְלָקֳדָם כַּפֻּרְתָּא:
@16 וִיכַפֵּר עַל קוּדְשָׁא מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל וּמִמֶרְדֵיהוֹן לְכָל חֲטָאֵיהוֹן וְכֵן יַעְבֵּד לְמַשְׁכַּן זִמְנָא דְשָׁרֵי עִמְהוֹן בְּגוֹ סוֹאֲבָתְהוֹן:
@17 וְכָל אֱנַשׁ לָא יְהֵי בְּמַשְׁכַּן זִמְנָא בְּמֵעֲלֵהּ לְכַפָּרָא בְקוּדְשָׁא עַד מִפְּקֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְעַל כָּל קְהָלָא דְיִשְׂרָאֵל:
@18 וְיִפּוֹק לְמַדְבְּחָא דִי קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי וְיִסַב מִדְמָא דְתוֹרָא וּמִדְמָא דִצְפִירָא וְיִתֵּן עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר:
@19 וְיַדֵי עֲלוֹהִי מִן דְמָא בְּאֶצְבְּעֵהּ שְׁבַע זִמְנִין וִידַכִּנֵהּ וִיקַדְשִׁנֵהּ מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל:
@20 וִישֵׁיצֵי מִלְכַפָּרָא עַל קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא וִיקָרֵב יָת צְפִירָא חַיָא:
@21 וְיִסְמוֹךְ אַהֲרֹן יָת תַּרְתֵּין יְדוֹהִי עַל רֵישׁ צְפִירָא חַיָא וִיוַדֵי עֲלוֹהִי יָת כָּל עֲוָיַת בְּנֵי יִשְׂרָאֵל וְיָת כָל מֶרְדֵיהוֹן לְכָל חֲטָּאֵיהוֹן וְיִתֵּן יָתְהוֹן עַל רֵישׁ צְפִירָא וִישַׁלַח בְּיַד גְבַר דִזְמִין לִמְהַךְ לְמַדְבְּרָא:
@22 וְיִטוֹל צְפִירָא עֲלוֹהִי יָת כָּל חוֹבֵיהוֹן לְאַרְעָא דְלָא יָתְבָא וִישַׁלַח יַת צְפִירָא בְּמַדְבְּרָא:
@23 וְיֵיעוֹל אַהֲרֹן לְמַשְׁכַּן זִמְנָא וְיַשְׁלַח יָת לְבוּשֵׁי בוּצָא דִי לְבַשׁ בְּמֵעֲלֵהּ לְקוּדְשָׁא וְיַצְנִעוּן תַּמָן:
@24 וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא בַּאֲתַר קַדִישׁ וְיִלְבַּשׁ יָת לְבוּשׁוֹהִי וְיִפּוֹק וְיַעְבֵּד יָת עֲלָתֵהּ וְיָת עֲלַת עַמָא וִיכַפַּר עֲלוֹהִי וְעַל עַמָּא:
@25 וְיָת תַּרְבָּא דְחַטָאתָא יַסֵק לְמַדְבְּחָא:
@26 וּדְמוֹבִיל יָת צְפִירָא לַעֲזָאזֵל יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:
@27 וְיָת תּוֹרָא דְחַטָאתָא וְיָת צְפִירָא דְחַטָאתָא דִי אִתָּעַל מִדִמְהוֹן לְכַפָּרָא בְקוּדְשָׁא יִתַּפְּקוּן לְמִבָּרָא לְמַשְּׁרִיתָא וְיוֹקְדוּן בְּנוּרָא יָת מַשְׁכֵּיהוֹן וְיָת בִּסְרְהוֹן וְיָת אָכְלֵיהוֹן:
@28 וּדְמוֹקִיד יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל למַשְׁרִיתָא:
@29 וּתְהֵי:לְכוֹן לִקְיַם עָלָם בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא תְּעַנוּן יָת נַפְשָׁתֵיכוֹן וְכָל עִבִידָא לָא תַעְבְּדוּן יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@30 אֲרֵי בְיוֹמָא הָדֵין יְכַפֵּר עֲלֵיכוֹן לְדַכָּאָה יָתְכוֹן מִכָּל חוֹבֵיכוֹן קֳדָם יְיָ תִּדְכּוּן:
@31 שְׁבַת שְׁבָתָא הִיא לְכוֹן וּתְעַנוּן יָת נַפְשָּׁתֵיכוֹן קְיַם עֲלָם:
@32 וִיכַפֵּר כַּהֲנָא דִי רַבִּי יָתֵהּ וְדִי יְקָרֵב יָת קֻרְבָּנֵהּ לְשַׁמָשָׁא תְּחוֹת אֲבוּהִי וְיִלְבַּשׁ יָת לְבוּשֵׁי בוּצָא:לבוּשֵׁי קוּדְשָׁא:
@33 וִיכַפֵּר עַל מִקְדַשׁ קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא יְכַפַּר וְעַל כַּהֲנַיָא וְעַל כָּל עַמָא דִקְהָלָא יְכַפַּר:
@34 וּתְהֵי דָא לְכוֹן לִקְיַם עָלָם לְכַפָּרָא עַל בְּנֵי יִשְׂרָאֵל מִכָּל חוֹבֵיהוֹן חֲדָא בְּשַׁתָּא וַעֲבַד כְּמָא דִי פַּקִיד יְיָ יָת מֹשֶׁה:
@35 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@36 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֵימָר:
@37 גְבַר גְבַר מִבֵּית יִשְׂרָאֵל דִי יִכּוֹס תּוֹר אוֹ אִמַר אוֹ עִזָא בְּמַשְׁרִיתָא אוֹ דִי יִכּוֹס מִבָּרָא לְמַשְׁרִיתָא:
@38 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתֵהּ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ קֳדָם מַשְׁכְּנָא דַיְיָ דְמָא יִתְחַשַׁב לְגַבְרָא הַהוּא דְמָא אֲשַׁד וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מִגוֹ עַמֵהּ:
@39 בְּדִיל דִי יַיְתוּן בְּנֵי יִשְׂרָאֵל יָת דִבְחֵיהוֹן דִי אִנוּן דָבְחִין עַל אַפֵּי חַקְלָא וְיַיְתוּנוּן לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא לְוָת כַּהֲנָא וְיִכְסוּן נִכְסַת קוּדְשִׁין קֳדָם יְיָ יָתְהוֹן:
@40 וְיִזְרוֹק כַּהֲנָא יָת דְמָא עַל מַדְבְּחָא דַיְיָ בִּתְרַע מַשְׁכַּן זִמְנָא וְיַסֵק תַּרְבָּא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@41 וְלָא יִדְבְּחוּן עוֹד יָת דִבְחֵיהוֹן לַשֵׁדִין דִי אִנוּן טָעָן בַּתְרֵיהוֹן קְיַם עָלָם תְּהֵי דָא לְהוֹן לְדָרֵיהוֹן:
@42 וּלְהוֹן תֵּימַר גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יַסֵק עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָא:
@43 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתִנֵהּ לְמֶעְבַּד יָתֵהּ קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@44 וּגְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יֵיכוּל כָּל דְמָא וְאֶתֵּן רוּגְזִי בַּאֲנָשָׁא דְיֵיכוּל יָת דְמָא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@45 אֲרֵי נְפַשׁ בִּסְרָא בִּדְמָא הִיא וַאֲנָא יְהָבִתֵּהּ לְכוֹן עַל מַדְבְּחָא לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן אֲרֵי דְמָא הוּא עַל נַפְשָׁא מְכַפֵּר:
@46 עַל כֵּן אֲמָרִית לִבְנֵי יִשְׂרָאֵל כָּל אֱנַשׁ מִנְכוֹן לָא יֵיכוּל דְמָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן לָא יֵיכוּל דְמָא:
@47 וּגְבַר גְבַר מִן בְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יְצוּד צֵידָא חַיְתָא אוֹ עוֹפָא דִי מִתְאֲכֵל וְיֵשׁוֹד יָת דְמֵהּ וִיכַסִנֵהּ בְּעַפְרָא:
@48 אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ בְּנַפְשֵׁהּ הוּא וַאֲמָרִית לִבְנֵי יִשְׂרָאֵל דַם כָּל בִּסְרָא לָא תֵיכְלוּן אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ הִיא כָּל דְיֵיכְלִנֵהּ יִשְׁתֵּיצֵי:
@49 וְכָל אֱנַשׁ דִי יֵיכוּל נְבִילָא וּתְבִירָא בְּיַצִיבָא וּבְגִיוֹרָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@50 וְאִם לָא יְצַבַּע וּבִסְרֵהּ לָא יַסְחֵי וִיקַבֵּל חוֹבֵהּ:
@51 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@52 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@53 כְּעוֹבָדֵי עַמָא דְאַרְעָא דְמִצְרַיִם דִי יְתֶבְתּוּן בַּהּ לָא תַעְבְּדוּן וּכְעוֹבָדֵי עַמָא דְאַרְעָא דִכְנַעַן דִי אֲנָא מָעֵל יָתְכוֹן תַּמָן לָא תַעְבְּדוּן וּבְנִימוֹסֵיהוֹן לָא תְהָכוּן:
@54 יָת דִינַי תַּעְבְּדוּן וְיָת קְיָמַי תִּטְרוּן לְהַלָכָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@55 וְתִטְרוּן יָת קְיָמַי וְיָת דִינַי דִי יַעְבֵּד יָתְהוֹן אֲנָשָׁא וְיֵחֵי בְהוֹן לְחַיֵי עָלְמָא אֲנָא יְיָ:
@56 גְבַר גְבַר לְכָל קָרִיב בִּסְרֵהּ לָא תִקְרְבוּן לְגַלָאָה עֶרְיָא אֲנָא יְיָ:
@57 עֶרְיַת אֲבוּךְ וְעֶרְיַת אִמָךְ לָא תְגַלֵי אִמָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@58 עֶרְיַת אִתַּת אָבוּךְ לָא תְגַלֵי עֶרְיַת אָבוּךְ הִיא:
@59 עֶרְיַת אֲחָתָךְ בַּת אֲבוּךְ אוֹ בַת אִמָךְ דִילִידָא מִן אֲבוּךְ מִן אִתַּת אָחֳרִי אוֹ מִן אִמָךְ לִגְבַר אָחֳרָן לָא תְגַלֵי עֶרְיַתְהֶן:
@60 עֶרְיַת בַּת בְּרָךְ אוֹ בַת בְּרַתָּךְ לָא תְגַלֵי עֶרְיַתְהֶן אֲרֵי עֶרְיְתָךְ אִנוּן:
@61 עֶרְיַת בַּת אִתַּת אֲבוּךְ דִילִידָא מִן אֲבוּךְ אֲחָתָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@62 עֶרְיַת אֲחַת אֲבוּךְ לָא תְגַלֵי קָרִיבַת אֲבוּךְ הִיא:
@63 עֶרְיַת אֲחַת אִמָךְ לָא תְגַלֵי אֲרֵי קָרִיבַת אִמָךְ הִיא:
@64 עֶרְיַת אַח אֲבוּךְ לָא תְגַלֵי לְאִתְּתֵהּ לָא תִקְרַב אִתַּת אַח אֲבוּךְ הִיא:
@65 עֶרְיַת כַּלָתָךְ לָא תְגַלֵי אִתַּת בְּרָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@66 עֶרְיַת אִתַּת אֲחוּךְ לָא תְגַלֵי עֶרְיַת אֲחוּךְ הִיא:
@67 עֶרְיַת אִתְּתָא וּבְרַתָּהּ לָא תְגַלֵי יָת בַּת בְּרָהּ וְיָת בַּת בְּרַתָּהּ לָא תִםַב לְגַלָאָה עֶרְיָתָהּ קָרִיבָן אִנוּן עֵצַת חִטְאִין הִיא:
@68 וְאִתְּתָא עִם אֲחָתָהּ לָא תִסָב לְעָקָאָה לְגַלָאָה עֶרְיְתָהּ עֲלָהּ בְּחַיָיהָא:
@69 וּלְאִתְּתָא בְּרִחוּק סוֹבְתַהּ לָא תִקְרַב לְגַלָאָה עֶרְיְתָהּ:
@70 וּבְאִתַּת חַבְרָךְ לָא תִתֵּן שְׁכֻבְתָּךְ לְזַרְעָא לְאִסְתָּאָבָא בָהּ:
@71 וּמִבְּנָיִךְ לָא תִתֵּן לְאַעְבָּרָא לְמוֹלֶךְ וְלָא תַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@72 וְעִם דְכוּרָא לָא תִשְׁכּוּב מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא הִיא:
@73 וּבְכָל בְּעִירָא לָא תִתֵּן שְׁכֻבְתָּךְ לְאִסְתָּאָבָא בָהּ וְאִתְּתָא לָא תְקוּם קֳדָם בְּעִירָא לְמִשְׁלַט בָּהּ תִּבְלָא הוּא:
@74 לָא תִסְתַּאֲבוּן בְּכָל אִלֵין אֲרֵי בְּכָל אִלֵין אִסְתַּאָבוּ עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן:
@75 וְאִסְתָּאָבַת אַרְעָא וְאַסְעָרִית חוֹבָהּ עֲלָהּ וְרוֹקֵינַת אַרְעָא יָת יָתְבָהָא:
@76 וְתִטְרוּן אַתּוּן יָת קְיָמַי וְיָת דִינַי וְלָא תַעְבְּדוּן מִכֹּל תּוֹעֶבְתָּא הָאִלֵין יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@77 אֲרֵי יָת כָּל תּוֹעֶבְתָּא הָאִלֵין עֲבָדוּ אֱנָשֵׁי אַרְעָא דִי קֳדָמֵיכוֹן וְאִסְתָּאָבַת אַרְעָא:
@78 וְלָא תְרוֹקֵן אַרְעָא יָתְכוֹן בְּסָאֳבֵיכוֹן יָתָהּ כְּמָא דְרוֹקֵינַת יָת עַמְמַיָא דִי קֳדָמֵיכוֹן:
@79 אֲרֵי כָּל דִי יַעְבֵּד מִכֹּל תּוֹעֶבְתָּא הָאִלֵין וְיִשְׁתֵּיצוּן נַפְשָׁתָא דְיַעְבְּדוּן מִגוֹ עַמְהוֹן:
@80 וְתִטְרוּן יָת מַטְרַת מֵימְרִי בְּדִיל דְלָא לְמֶעְבַּד מִנִימוֹסֵי תוֹעֶבְתָּא דְאִתְעֲבָדָא קֳדָמֵיכוֹן וְלָא תִסְתַּאֲבוּן בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן: פפפ:

@1 **וידבר ה' אל משה אחרי מות שני בני אהרן** וגו' **.** מה תלמוד לומר, היה רבי אלעזר בן עזריה מושלו משל לחולה שנכנס אצלו רופא. אמר לו אל תאכל צונן ואל תשכב בטחב. בא אחר ואמר לו אל תאכל צונן ואל תשכב בטחב שלא תמות כדרך שמת פלוני. זה זרזו יותר מן הראשון, לכך נאמר אחרי מות שני בני אהרן:
@2 **ויאמר ה' אל משה דבר אל אהרן אחיך ואל יבא.** שלא ימות כדרך שמתו בניו: **ולא ימות.** שאם בא הוא מת: **כי בענן אראה.** כי תמיד אני נראה שם עם עמוד ענני. ולפי שגלוי שכינתי שם, יזהר שלא ירגיל לבא, זהו פשוטו. ומדרשו לא יבא כי אם בענן הקטרת ביום הכפורים:
@3 **בזאת.** גימטריא שלו ארבע מאות ועשר, רמז לבית ראשון: **בזאת יבא אהרן** וגו' **.** ואף זו לא בכל עת, כי אם ביום הכפורים, כמו שמפורש בסוף הפרשה (פסוק כט) בחדש השביעי בעשור לחדש:
@4 **כתנת בד** וגו' **.** מגיד שאינו משמש לפנים בשמונה בגדים שהוא משמש בהם בחוץ, שיש בהם זהב, לפי שאין קטגור נעשה סנגור, אלא בארבעה, ככהן הדיוט, וכלן של בוץ: **קדש ילבש.** שהיו משל קדש: **יצנף.** כתרגומו יחית ברישיה, יניח בראשו, כמו (בראשית לט טז) ותנח בגדו ואחתתיה: **ורחץ במים.** אותו היום טעון טבילה בכל חליפותיו. וחמש פעמים היה מחליף מעבודת פנים לעבודת חוץ ומחוץ לפנים, ומשנה מבגדי זהב לבגדי לבן ומבגדי לבן לבגדי זהב, ובכל חליפה טעון טבילה ושני קדושי ידים ורגלים מן הכיור:
@6 **את פר החטאת אשר לו.** האמור למעלה. ולמדך כאן שמשלו הוא בא, ולא משל צבור: **וכפר בעדו ובעד ביתו.** מתודה עליו עונותיו ועונות ביתו:
@8 **ונתן אהרן על שני השעירים גרלות.** מעמיד אחד לימין ואחד לשמאל, ונותן שתי ידיו בקלפי ונוטל גורל בימין וחברו בשמאל, ונותן עליהם, את שכתוב בו לשם הוא לשם, ואת שכתוב בו לעזאזל משתלח לעזאזל: **עזאזל.** הוא הר עז וקשה, צוק גבוה, שנאמר (פסוק כב) ארץ גזרה, חתוכה:
@9 **ועשהו חטאת.** כשמניח הגורל עליו קורא לו שם ואומר לה' חטאת:
@10 **יעמד חי.** כמו יעמד חי על ידי אחרים, ותרגומו יתקם כד חי. מה תלמוד לומר חי, לפי שנאמר לשלח אתו לעזאזל, ואיני יודע שלוחו אם למיתה אם לחיים, לכך נאמר יעמד חי, עמידתו חי עד שישתלח, מכאן ששלוחו למיתה: **לכפר עליו.** שיתודה עליו, כדכתיב (פסוק כא) והתודה עליו וגו' :
@11 **וכפר בעדו** וגו' **.** ודוי שני עליו ועל אחיו הכהנים, שהם כלם קרויים ביתו, שנאמר (תהלים קלה יט) בית אהרן ברכו את ה' וגו' , מכאן שהכהנים מתכפרים בו, וכל כפרתן אינה אלא על טמאת מקדש וקדשיו, כמו שנאמר (פסוק טז) וכפר על הקדש מטמאות וגו' :
@12 **מעל המזבח.** החיצון: **מלפני ה'.** מצד שלפני הפתח והוא צד מערבי: **דקה.** מה תלמוד לומר דקה, והלא כל הקטורת דקה היא, שנאמר (שמות ל לו) ושחקת ממנה הדק, אלא שתהא דקה מן הדקה, שמערב יום הכפורים היה מחזירה למכתשת:
@13 **על האש.** שבתוך המחתה: **ולא ימות.** הא אם לא עשאה כתקנה, חיב מיתה:
@14 **והזה באצבעו.** הזאה אחת במשמע: **ולפני הכפרת יזה שבע.** הרי אחת למעלה ושבע למטה:
@15 **אשר לעם.** מה שהפר מכפר על הכהנים מכפר השעיר על ישראל, והוא השעיר שעלה עליו הגורל לשם: **כאשר עשה לדם הפר.** אחת למעלה ושבע למטה:
@16 **מטמאת בני ישראל.** על הנכנסין למקדש בטמאה ולא נודע להם בסוף, שנאמר לכל חטאתם, וחטאת היא שוגג: **ומפשעיהם.** אף הנכנסין מזיד בטמאה: **וכן יעשה לאהל מועד.** כשם שהזה משניהם בפנים אחת למעלה ושבע למטה, כך מזה על הפרוכת מבחוץ משניהם אחת למעלה ושבע למטה: **השכן אתם בתוך טמאתם.** אף על פי שהם טמאים שכינה ביניהם:
@18 **אל המזבח אשר לפני ה'.** זה מזבח הזהב שהוא לפני ה' בהיכל. ומה תלמוד לומר ויצא, לפי שהזה ההזאות על הפרוכת ועמד מן המזבח ולפנים והזה, ובמתנות המזבח הזקיקו לצאת מן המזבח ולחוץ, ויתחיל מקרן מזרחית צפונית: **וכפר עליו.** ומה היא כפרתו, ולקח מדם הפר ומדם השעיר, מעורבין זה לתוך זה:
@19 **והזה עליו מן הדם.** אחר שנתן מתנות באצבעו על קרנותיו, מזה שבע הזאות על גגו: **וטהרו.** ממה שעבר: **וקדשו.** לעתיד לבא:
@21 **איש עתי.** המוכן לכך מיום אתמול:
@23 **ובא אהרן אל אהל מועד.** אמרו רבותינו, שאין זה מקומו של מקרא זה, ונתנו טעם לדבריהם במסכת יומא (דף לב א) ואמרו כל הפרשה כלה אמורה על הסדר, חוץ מביאה זו, שהיא אחר עשית עולתו ועולת העם והקטרת אימורי פר ושעיר שנעשים בחוץ בבגדי זהב, וטובל ומקדש ופושטן ולובש בגדי לבן: **ובא אל אהל מועד.** להוציא את הכף ואת המחתה שהקטיר בה הקטרת לפני ולפנים: **ופשט את בגדי הבד.** אחר שהוציאם ולובש בגדי זהב לתמיד של בין הערבים. וזהו סדר העבודות תמיד של שחר בבגדי זהב, ועבודת פר ושעיר הפנימיים וקטרת של מחתה בבגדי לבן, ואילו ואיל העם ומקצת המוספין בבגדי זהב, והוצאת כף ומחתה בבגדי לבן, ושירי המוספין ותמיד של בין הערבים וקטורת ההיכל שעל מזבח הפנימי בבגדי זהב. וסדר המקראות לפי סדר העבודות כך הוא ושלח את השעיר במדבר, ורחץ את בשרו במים וגו' ויצא ועשה את עולתו וגו' ואת חלב החטאת וגו' . וכל הפרשה עד ואחרי כן יבא אל המחנה, ואחר כך ובא אהרן: **והניחם שם.** מלמד שטעונין גניזה, ולא ישתמש באותן ארבעה בגדים ליום כפורים אחר:
@24 **ורחץ את בשרו** וגו' **.** למעלה למדנו מורחץ את בשרו ולבשם (פסוק ד) , שכשהוא משנה מבגדי זהב לבגדי לבן טעון טבילה, שבאותה טבילה פשט בגדי זהב שעבד בהן עבודת תמיד של שחר ולבש בגדי לבן לעבודת היום, וכאן למדנו שכשהוא משנה מבגדי לבן לבגדי זהב טעון טבילה: **במקום קדוש.** המקדש בקדשת עזרה והיא היתה בגג בית הפרוה, וכן ארבע טבילות הבאות חובה ליום, אבל הראשונה היתה בחול: **ולבש את בגדיו.** שמונה בגדים שהוא עובד בהן כל ימות השנה: **ויצא.** מן ההיכל אל החצר שמזבח העולה שם: **ועשה את עלתו.** איל לעולה האמור למעלה (פסוק ג) בזאת יבא אהרן וגו' : **ואת עלת העם.** ואיל אחד לעולה האמור למעלה (פסוק ה) ומאת עדת בני ישראל וגו' :
@25 **ואת חלב החטאת.** אימורי פר ושעיר: **יקטיר המזבחה.** על מזבח החיצון, דאלו בפנימי כתיב (שמות ל ט) לא תעלו עליו קטרת זרה ועולה ומנחה:
@27 **אשר הובא את דמם.** להיכל ולפני ולפנים:
@32 **וכפר הכהן אשר ימשח** וגו' **.** כפרה זו של יום הכפורים אינה כשרה אלא בכהן גדול, לפי שנאמרה כל הפרשה באהרן, הצרך לומר בכהן גדול הבא אחריו שיהא כמוהו: **ואשר ימלא את ידו.** אין לי אלא המשוח בשמן המשחה, מרבה בגדים מנין, תלמוד לומר ואשר ימלא את ידו וגו' , והם כל הכהנים הגדולים שעמדו מיאשיהו ואילך, שבימיו נגנזה צלוחית של שמן המשחה: **לכהן תחת אביו.** ללמד שאם בנו ממלא את מקומו הוא קודם לכל אדם:
@34 **ויעש כאשר צוה ה'** וגו' **.** כשהגיע יום הכפורים עשה כסדר הזה, ולהגיד שבחו של אהרן שלא היה לובשן לגדלתו, אלא כמקיים גזרת המלך:
@37 **אשר ישחט שור או כשב.** במקדשין הכתוב מדבר, שנאמר להקריב קרבן: **במחנה.** חוץ לעזרה:
@38 **דם יחשב.** כשופך דם האדם שמתחייב בנפשו: **דם שפך.** לרבות את הזורק דמים בחוץ:
@39 **אשר הם זבחים.** אשר הם רגילים לזבוח:
@41 **לשעירם.** לשדים, כמו (ישעיה יג כא) ושעירים ירקדו שם:
@42 **אשר יעלה עלה.** לחיב על המקטיר איברים בחוץ כשוחט בחוץ, שאם שחט אחד והעלה חברו שניהם חיבין:
@43 **ונכרת.** זרעו נכרת וימיו נכרתין:
@44 **כל דם.** לפי שנאמר בנפש יכפר, יכול לא יהא חיב אלא על דם המקדשים, תלמוד לומר כל דם: **ונתתי פני.** פנאי שלי, פונה אני מכל עסקי ועוסק בו:
@45 **כי נפש הבשר.** של כל בריה בדם היא תלויה, ולפיכך נתתיו על המזבח לכפר על נפש האדם. תבוא נפש ותכפר על הנפש:
@46 **כל נפש מכם.** להזהיר גדולים על הקטנים:
@47 **אשר יצוד.** אין לי אלא ציד, אוזין ותרנגולין מנין, תלמוד לומר ציד מכל מקום. אם כן למה נאמר אשר יצוד, שלא יאכל בשר אלא בהזמנה הזאת: **אשר יאכל.** פרט לטמאים:
@48 **דמו בנפשו הוא.** דמו הוא לו במקום הנפש, שהנפש תלויה בו: **כי נפש כל בשר דמו הוא.** הנפש היא הדם. דם ובשר לשון זכר' נפש לשון נקבה:
@49 **אשר תאכל נבלה וטרפה.** בנבלת עוף טהור דבר הכתוב' שאין לה טמאה אלא בשעה שנבלעת בבית הבליעה' ולמדך כאן שמטמאה באכילתה' ואינה מטמאה במגע. וטרפה האמורה כאן לא נכתבה אלא לדרוש. וכן שנינו יכול תהא נבלת עוף טמא מטמאה בבית הבליעה' תלמוד לומר טרפה' מי שיש במינו טרפה' יצא עוף טמא שאין במינו טרפה:
@50 **ונשא עונו.** אם יאכל קדש או יכנס למקדש חיב על טמאה זו ככל שאר טמאות: **ובשרו לא ירחץ ונשא עונו.** על רחיצת גופו ענוש כרת ועל כבוס בגדים במלקות:
@52 **אני ה' אלהיכם.** אני הוא שאמרתי בסיני (שמות כ ב) אנכי ה' אלהיך, וקבלתם עליכם מלכותי, מעתה קבלו גזרותי. רבי אומר גלוי וידוע לפניו שסופן לנתק בעריות בימי עזרא, לפיכך בא עליהם בגזרה אני ה' אלהיכם, דעו מי גוזר עליכם, דין להפרע ונאמן לשלם שכר:
@53 **כמעשה ארץ מצרים.** מגיד שמעשיהם של מצריים ושל כנעניים מקלקלים מכל האמות, ואותו מקום שישבו בו ישראל מקלקל מן הכל: **אשר אני מביא אתכם שמה.** מגיד שאותן עממין שכבשו ישראל מקלקלים יותר מכלם: **ובחקתיהם לא תלכו.** מה הניח הכתוב שלא אמר, אלא אלו נמוסות שלהן, דברים החקוקין להם, כגון טרטיאות ואצטדיאות. רבי מאיר אומר אלו דרכי האמורי שמנו חכמים:
@54 **את משפטי תעשו.** אלו דברים האמורים בתורה במשפט, שאלו לא נאמרו, היו כדאי לאמרן: **ואת חקתי תשמרו.** דברים שהם גזרת המלך, שיצר הרע משיב עליהם, למה לנו לשמרן, ואמות העולם משיבין עליהם, כגון אכילת חזיר ולבישת שעטנז וטהרת מי חטאת, לכך נאמר אני ה' גזרתי עליכם, אי אתם רשאים להפטר: **ללכת בהם.** אל תפטר מתוכם, שלא תאמר למדתי חכמת ישראל אלך ואלמד חכמת האמות:
@55 **ושמרתם את חקתי** וגו' **.** לרבות שאר דקדוקי הפרשה, שלא פרט הכתוב בהם. דבר אחר לתן שמירה ועשייה לחקים ושמירה ועשייה למשפטים, לפי שלא נתן אלא עשייה למשפטים ושמירה לחקים: **וחי בהם.** לעולם הבא, שאם תאמר בעולם הזה, והלא סופו הוא מת: **אני ה'.** נאמן לשלם שכר:
@56 **לא תקרבו.** להזהיר הנקבה כזכר, לכך נאמר לשון רבים: **אני ה'.** נאמן לשלם שכר:
@57 **ערות אביך.** זו אשת אביך, או אינו אלא כמשמעו, נאמר כאן ערות אביך, ונאמר להלן (ויקרא כ יא) ערות אביו גלה, מה להלן אשת אביו, אף כאן אשת אביו: **וערות אמך.** להביא אמו שאינה אשת אביו:
@58 **ערות אשת אביך.** לרבות לאחר מיתה:
@59 **בת אביך.** אף בת אנוסה במשמע: **מולדת בית או מולדת חוץ.** בין שאומרים לו לאביך קים את אמה ובין שאומרים לו לאביך הוצא את אמה, כגון ממזרת או נתינה:
@60 **ערות בת בנך.** בבתו מאנוסתו הכתוב מדבר, ובתו ובת בתו מאשתו אנו למדין מערות אשה ובתה לא תגלה, בין שהיא ממנו ובין שהיא מאיש אחר: **ערות בת בנך.** קל וחמר לבתך, אלא לפי שאין מזהירין מן הדין למדוה מגזרה שוה במסכת יבמות (ג א) :
@61 **ערות בת אשת אביך.** למד שאינו חיב על אחותו משפחה ונכרית לכך נאמר בת אשת אביך בראויה לקדושין:
@64 **ערות אחי אביך לא תגלה.** ומה היא ערותו, אל אשתו לא תקרב:
@65 **אשת בנך היא.** לא אמרתי אלא בשיש לבנך אישות בה, פרט לאנוסה ושפחה ונכרית:
@67 **ערות אשה ובתה.** לא אסר הכתוב אלא על ידי נשואי הראשונה, לכך נאמר לא תקח, לשון קיחה, וכן לענין הענש אשר יקח את אשה ואת אמה (ויקרא כ יד) , לשון קיחה, אבל אנס אשה מתר לשא בתה: **שארה הנה.** קרובות (הן) זו לזו: **זמה.** עצה כתרגומו עצת חטאין, שיצרך יועצך לחטוא:
@68 **אל אחתה.** שתיהן כאחת: **לצרר.** לשון צרה לעשות את זו צרה לזו: **בחייה.** למדך שאם גרשה לא ישא את אחותה כל זמן שהיא בחיים:
@71 **למלך.** עבודה זרה היא ששמה מולך, וזו היא עבודתה, שמוסר בנו לכומרים ועושין שתי מדורות גדולות ומעבירין את הבן ברגליו בין שתי מדורות האש: **לא תתן.** זו היא מסירתו לכומרים: **להעביר למלך.** זו (היא) העברת האש:
@73 **תבל הוא.** לשון קדש וערוה ונאוף, וכן ואפי על תבליתם (ישעיה י כה) . דבר אחר תבל הוא לשון בלילה וערבוב, זרע אדם וזרע בהמה:
@78 **ולא תקיא הארץ אתכם.** משל לבן מלך שהאכילוהו דבר מאוס, שאין עומד במעיו אלא מקיאו, כך ארץ ישראל אינה מקימת עוברי עברה. ותרגומו ולא תרוקין, לשון רקון, מריקה עצמה מהם:
@79 **הנפשות העשת.** הזכר והנקבה במשמע:
@80 **ושמרתם את משמרתי.** להזהיר בית דין על כך: **ולא תטמאו בהם אני ה' אלהיכם.** הא אם תטמאו, אני אלהיכם, ואתם נפסלים מאחרי, ומה הנאה יש לי בכם, ואתם מתחיבים כליה, לכך נאמר אני ה' אלהיכם:

@1 **אחרי מות שני בני אהרן בקרבתם לפני יי' וימותו.** ר"ל בקרבתם לפני יי' להקטיר הקטרת ויהיה עניינו כטעם בגשתם אל המזבח או יהיה זה חטא שני לבני אהרן רוצה לומר שבאו לפני לפנים ובעבור כן סמך לזה הספור אמרו דבר אל אהרן אחיך ואל יבא בכל עת אל הקדש והביאור הראשון הוא יותר נכון לפי מה שאחשוב ואמנם סמך לזה הספור זאת האזהרה לבאר שהדברים שהעונש עליהם מיתה בידי שמים אין ראוי להקל בהם כי השם יתע' יקח נקמתו מהאיש העובר עליהם כמו שלקחה מבני אהן ולזה ראוי שייראו מאד מעבור על כל אלו האזהרות והנה לא בארה התורה מה היה זה הדבור ואפשר שיהיה הדבור ההוא הוא הדבור הנזכר אחר זה במה שאמר ויאמר יי' אל משה דבר אל אהרן אחיך ויהיה כפול המאמר בזה בטעם אמרו תחלת דבר יי' בהושע ויאמר יי' אל הושע ואפשר שרמז בזה המקום אל הדבור הנזכר בפרשת שמיני שהיה אחרי מות שני בני אהרן והם האזהרות שנזכרות שם שנתחייבו עליהם הכהנים מיתה בידי שמים והנה זה הענין שזכר בזה המקום מעבודת יום הכיפורים היה אז ואמנם הפסיקה התורה בין שני אל המאמרים וזכרה ענין המאכלות אסורות והמותרות והטמאות והטהרות כי עבודת יום הכיפורים היתה מכוונת לנקות הטמאות כמו שיתבאר ולזה זכר' אותם התורה קודם שתזכיר זאת הפרשה והנה נזכרו המאכלות קודם הטמאות לפי שענינם מתיחס כמו שהתבאר מדברינו במה שקדם:
@2 **ואל יבא בכל עת אל הקדש מבית לפרכת.** רוצה לומר בבית קדשי הקדשים:
@2 **אל פני הכפרת אשר על הארון ולא ימות.** באר שאם יבא שם בזולת זה האופן שזכר בזאת הפרשה אפילו ביום הכיפורים שצוהל הכנס שם יתחייב מיתה שנאמר בזאת יבא אהרן אל הקדש רוצה לומר בזה האופן לא בזולתו ולא בזולתי היום הזה מהשנה והוא העשירי לחדש שביעי כמו שנזכר בזאת הפרשה וראוי שתדע כי בבית שני לא היה שם ארון כי כבר גנזו יאשיהו ועם כל זה היה שם קדש הקדשים והיה שם צורת כרובים להורות על מציאות הצורות הנבדלות אשר בעבורו היה קדש הקדשי' אף על פי שאין שם ארון וכפרת ולהעיר על שאין ארון וכפרת מעכבים זאת העבוד אמר אחר זה בזאת יבא אהרן אל הקדש:
@2 **כי בענן אראה על הכפרת.** רוצה לזמר שכבודי נראה משם בענן וממנו מגעת הנבואה כמו שאמר ונועדתי לך וגומר. ולזה ראוי לתת מעלה וכבוד לזה המקום הנכבד שמעיר על אופן הגעת הנבואה ועל מציאות הצורות הנבדלות ולזה היה נראה שם על צד המופת בעת הגעת הנבואה למשה ענן להעיר כי שם מה שיעיר על הנמצא אשר ישפיע הנבואה שהאדם לא יכול להשיגו השגה שלמה כמו שלא יושג בשלמות המוחש לחוש הראות כשהיה ענן בין החוש והמוחש ולהיות העניין כן הנה אין ראוי שיתמידו להכנס בזה המקום הנכבד כי זה מה שיפחית מעלתו בנפש ויהיה זה סבה אל שתעלם הכונה שכונה התורה בענינו:
@3 **בזאת יבא אהרן אל הקדש וגומר.** ראוי שתדע שזה יהיה אחר הקריבו תמיד של שחר עם שאר העבודות הנעשות אז כמו הקטרת הקטרת והטבת הנרות כי כבר התבאר שאין קרבן קרב קודם תמיד של שחר והנה יתבאר אחר זה איך יקריב אלו הקרבנות:
@4 **כתנת בד קדש ילבש וגומר.** למדנו מזה שהוא משמש בעבודות המתיחסות לכפרת היום בבגדי לבן והם של פשתן ולא יחוייב בחוטן שיהיה כפול ששה שנאמר בד ולא ישמש אלא בד' בגדים והנה העבודות המיוחסות לכפרת היום הם חטאתו וחטאת העם ושעיר המשתלח הנזכרים בזאת הפרשה והכנסת הקטרת לפני לפנים כי כל זה נזכר בזאת הפרשה אחרי זכירתו אלו הבגדים להורות שכל אלו העבודות בבגדי לבן הם נעשות ואולם עולתו ועולת העם והקטרת אמורי פר ושעיר הנשרפין היה בבגדי זהב רוצה לומר בשמנה בגדים אשר לכהן גדול אף על פי שיחשב היותו מיוחד לכפרת היום וזה שכבר אמרה התורה זה בביאור בזאת הפרשה שנאמר ורחץ את בשרו במים במקום קדוש ולבש את בגדיו ויצא ועשה את עולתו ואת עולת העם וגו'. ואת חלב החטאת יקטיר המזבחה. והיה זה כן כי שלמות הכפרה היא בחטאת כמו שהתבאר במה שקדם וכיון שנזרק דמו שלמה הכפרה ולזה לא תהיה הקטרת האמורי' של פר ושעיר מהעבודו' המיוחדו' לכפר' חיו' ולא עשיית עולתו ואת עולת העם והנה היו אלו העבודות בגדי לבן כי לחזק ההוראה שהיתה בהם על עניני החמר וחסרונו אשר הוא סבת הטומאה והחטאים שיכפר עליהם ביום הזה ראוי שיוסר ממנו זה הכבוד הנפלא שהיה לו בלובשו בגדי זהב וישמש בדמות הבגדים שישמש בהם כהן הדיוט הלא תראה של זאת הסבה נשרף הפר והשעיר חוץ לשלשה מחנו' ויטמא שורפם ושולח השעיר האחד לעזאזל ויטמא משלחו עם שהלובן מורה על הנקיון מהחטאים כאמרו אם יהיו חטאיכם כשנים כשלג ילבינו וזה גם כן ראוי שילבש בגדי לבן בעבודות אשר תהיינה לנקות מהחטאי' והוא מבוא עוד שאינו ראוי שיכנס לפני לפנים בבגדי זהב כי ראוי שיכיר היותו שפל ונבזה ביחס אל השם יתעלה והשכלים הנפרדים אשר מה שבמקום ההוא מעיר על מציאותם וראוי שלא יעלם ממנו שכל העבודות הנעשות ביום ההוא במקדש היו על יד כהן גדול וזה שאתה תמצא בכל הפרשה הזאת שעל יד אהרן תעשינה אלו העבודות המיוחדות לכפרה והבלתי מיוחדות לכפרה והנה בפרשת פינחס זכר בעבודת היום מוסף היום ושעיר חטאת מלבד חטאת הכפורים ומלבד עולת התמיד וזה ממה שיורה שעל ידי מי שיעשה חטאת יום הכפורים תעשה עולת התמיד ומוסף היום ושעיר חטאת השני אלא שלא יהיה בבגדי לבן כי אם מה שזכרנו:
@4 **ורחץ במים את בשרו ולבשם.** מצינו בזה המקום שבלבישתו בגדי הלבן יצטרך טבילה וכן מצינו במה שאחר זה כי בלבישתו בגדי זהב הוא טעון טבילה ומזה המקום נלמד שבכל עת שימיר מבגדי זהב לבגדי לבן או מבגדי לבן לבגדי זהב טעון טבילה. ומזה המקום יתבאר שהוא טעון קדוש ידים ורגלים בין בגדים לבגדים וזה כי גם כן במקומות שלא הצריכה התורה טבילה הצריכה קדוש ידים ורגלים כל שכן שיצטרך במקום שהוצרך לטבילה ואחשוב שהוצרכו אלו הטבילות הנוספות בזה היום להורות על חוזק ההנקות מאלו הדברים החמריים שהם סבת הטמאות והעברות שיכופר עליהם ביום הכפורים ולפי שהכפרה הזאת כוללת לכל ישראל חוייב שתהיה על יד הנכבד מהכהנים:
@5 **ומאת עדת בני ישראל יקח וגומר.** הנה זה היה לקוח ממה שהיה מכלל ישראל והם חציי השקלים המוכנים לכל עבודת אהל מעד ומזה המקום נלמד שהפר והאיל שהיה מביא כהן גדול היה משלו לא מכלל הצבור ואלו השני שעירות הם שעיר המשתלח ושעיר הנשרף בחוץ שניהם חטאת כמו שנבאר בזה הפסוק והנה תבא העולה אחריהם להורות שנשלם הרצוי:
@6 **והקריב אהרן את פר החטאת אשר לו וכפר בעדו ובעד ביתו.** ראוי שתדע שזאת הכפרה הוא ודוי דברים שהרי אמר אחר זה בשעיר המשתלח יעמד חי לפני ה' לכפר עליו. וכבר התבאר בזאת הפרשה שזאת הכפרה היא ודוי דברים שנאמר וסמך אהרן את שתי ידיו על ראש השעיר החי והתודה עליו את כל עונות בני ישראל. ומשם יתבאר שהודוי הוא אחר הסמיכה והנה זאת ההקרבה הוא שיביאהו לצפון העזרה ויהיה ראש הקרבן מצד המערב ופני הסומך גם כן לצד המערב ויתודה בעדו ובעד ביתו. וראוי שתדע כי ביתו יאמר על אשתו ויאמר על הכהנים הדיוטים שהם בניו. ולפי שאמר אחר זה וכפר בעדו ובעד ביתו ואמר בסוף הפרשה ועל הכהנים ועל כל עם הקהל יכפר למדנו שההודאה בביתו הנאמר ראשונה נאמר על אשתו וביתו הנאמר שנית מורה על הכהנים ולזה ראוי שיהיה לכהן גדול אשה ואז יתכן לו לעבוד עבודת יום הכיפורים והיה זה כן כדי שיהיה יותר נקי מהרהור מעניני המשגל לפי שיש לו פת בסלו:
@7 **ולקח את שני השעירי' והעמיד אות' לפני יי' פתח אהל מועד.** הנה העמדתם תהיה למזרח העזרה לפאת צפון ופניהם לפאת המערב שנ' לפני י' באופן שאשר יהיה ליי' מהם יקריבהו לפאת מערב לשחוט אותו שם שנאמר אחר זה והקריב אהרן את השעיר אשר עלה עליו הגורל ליי' ועשהו חטאת:
@8 **ונתן אהרן על שני השעירים גורלות גורל אחד ליי' וגורל אחד לעזאזל.** לפי שאמר על שני השעירים את שני השעירים שני שעירי עזים לחטאת וההמנות במספר יהיה ביותר שלם שבפנים באחדים השוים והמסכימים למדנו שראוי שיהיו שוים ושתהיה לקיחתם כאחד עד שיהיו שנים תמיד. וענין הגורלות לפי מה שיורה עליו הגדר הוא שישימו שני גורלות במקום מכוסה ויגיעו הדבר אשר בו הגורלות ויקחו ממנו אחד בזולת שיראוהו וישימיהו על אחד מהדברים אשר יפילו עליו הגורל והשני על השני ולזה ראוי שיהיו הגורלות שוים ומסכימים באופן שלא יוכר במשושם בהם דבר והמשל שאם היה אחד של אבן ואחד של עץ הנה יכיר הגורל איזהו במשושו אותו ויהיה ענינו כאלו לא היה שם גורל וכן הענין אם היו שניהם מדבר אחד נהיה האחד גדול והאחד קטן והנה אלו הגורלות היה כתוב באחד מהם להשם ובשני לעזאזל:
@9 **והקריב אהרן את השעיר אשר עלה עליו הגורל ליי' וגו'.** לפי ששניהם חטאת כמו שקדם הנה ראוי שיאמר הכהן שהוא ליי' חטאת והנה יעשהו חטאת לשם יתע' בזה המאמר רק בתחלת ענינו לא היה מבואר בו אם יהיה לשם יתע' או לעזאזל והנה יניעהו ויקריבהו לצד המערב בעת ההיא להורות שהוא יהיה קרב להשם יתעלה:
@10 **והשעיר אשר עלה עליו הגורל לעזאזל יעמד חי לפני יי' לכפר עליו לשלח אותו לעזאזל המדברה.** הנה זה השעיר אשר לעזאזל היה עומד חי יפניו למערב כדי שיתכפר עליו בהתודותו עליו כמו שיזכור אחר זה ולזה היה עומד שם עד השלימו הזאות דם הפר והשעיר כי אחר זה יתודה עליו ואחר זה ישלח אותו לעזאזל המדברה ולזה היה ראוי שיעמוד במקום אשר משם משתלח והוא אצל מזרח העזרה והנה עזאזל הוא מקום גבוה וקשה והיה במדבר שלא יעבד בו ולא יזרע:
@11 **והקריב אהרן את פר החטאת אשר לו וכפר בעדו ובעד ביתו ושחט את פר החטאת אשר לו.** רוצה לומר שיקריבהו עוד שנית לפאת מערב כדי שיהיה במקום שחיטתו ויסמוך עליו ויתודה בעדו ובעד הכהנים והנה יתבאר לשון זה הודוי והודוי הקודם במה שיבא בזאת הפרשה ותכף לסמיכתו וישחט את פר החטאת אשר לו. וראוי שתדע כי מפני שהיה מחוייב שיהי' הוא בעצמו מקבל הדם בכלי שרת בימין ובה ישחוט הנה לא ישחוט כי אם רוב הסימנין כדי שלא יצא דם הפר מפני זאת השחיטה ולפי שבזה האופן נשלמה השחיטה לפר הנה ישלים כהן אחר לחתך הסימנין והעורקין באופן שיצא הדם ואז יקבל הכהן הגדול הדם בכלי שרת כמשפט ואם יאמר אומר שהוא ראוי שתהיה השחיטה באופן שיצא ממנה הדם לחזות בו ולזה לא יכשר זה אלא בכהן גדול אמרנו לו שזה בלתי אפשר אם לא ישפך הדם ואולי ישפך ממנו באופן שלא ישאר ממנו כדי להזות וגם כן הנה לא חייבה התורה שיהיה על ידי כהן גדול כי אם השחיטה לא חתיכת הורידין ולזה יתכן חתיכתם על ידי כהן אחר ולפי שההזא' לא תהיה כי אם אחר הקטרת הקטורת לפני לפנים הנה יהיה אחד מהכהנים מנדנד הדם במזרק כדי שלא יקרש באופן שיוכל להזות ממנו:
@12 **ולקח מלא המחתה גחלי אש מעל המזבח מלפני יי'.** ר"ל מעל מזבח העולה מהמערכה שהיתה שם מוכנת לזה לצד המערב ולזה היו שם ד' מערכות ביום הכיפורים כמו שבארנו בפרשת צו ומזה המקום יש ללמד שמערכת האש אשר יביאוהו למזבח הקטרת הוא יותר מערבית מהמערכה הגדולה וראוי היה להיות כן כי מה שהוא נכנס לפנים הוא יותר ראוי שיהיה יותר מערבי ויותר מערבי היה מה שהיה נכנס לפני לפנים לזאת הסבה בעינה ולפי שאמר גחלי אש למדנו שלא יביאם שם אלא מעוכלות ולא עוממות אלא לוחשות וראוי שיהיה האש בכלם שנאמ' גחלי אש והיה זה כן כדי שלא יהיה מהם בעצמם עשן אבל יהיה כל העשן מקטרת הסמים וכדי שיעלה בקלות ראוי שיהיו הגחלים לוחשות ולא עוממות:
@12 **ומלא חפניו קטרת סמי' דקה והביא מבית לפרכת.** לפי שהקטרת היתה דקה כמו שאמר ושחקת ממנה הדק. למדנו שמחזיר ממנה למכתשת כדי שתהיה בתכלית הדקות באופן שיוכל לקחת משם מלא חפניו מהקטרת השחוקה שנית ולפי שאמר שיביא מבית לפרכת מלא חפניו עם לקיחתו מלא המחתה שהיא בהכרח בידו הימנית לפי מה שהתבאר מהשרשים הכוללים הנה ימדוד מלא חפניו מקטרת הסמים וישימהו בכף אחד לא בחפניו כי לא יוכל עם זה לשאת המחתה בידו ולזה ישא הכף בשמאלו עד אשר יניח המחתה בקדש הקדשים ואחר ישוב הקטרת לחפניו כמו שצותה התורה ומשם יתנהו על האש וכבר נתן הסבה בזה אחר שישלם ביאור זאת הפרשה:
@12 **והביא מבית לפרכת והביא את דמו אל מבית לפרכת.** רוצה לומר אף על פי שאין שם ארון וכפרת ולזה עשו זה בבית שני שהיו שם כמה נביאים והנה אחשוב שהיה הכפרת בבית שני עם הכרובים כי כבר הקפידה התורה בהזאת דם הפר ושעיר של יום הכיפורים שתהיה על פני הכפורת ולפני הכפרת:
@13 **ונתן את הקטרת על האש לפני יי'.** הנה יתבאר מזה שהוא יניח תחלה המחתה לפני לפנים לפני יי'. ר"ל לפני הארון ואחר כך יתן הקטרת עליה ולפי שהוא ראוי שיהיה הקטרת מלא חפניו כמו שנזכר בפסוק הקודם ומשם יתנהו על האש הנה יקח הכף בשיניו או באי זה צד שיוכל ויוציא משם בגודלו הקטרת עד שישיבה לחפניו ומשם יתן אותה על האש במה שיהיה ממנו לצד המערב שנ' לפני יי':
@13 **וכסה ענן הקטרת את הכפרת אשר על העדות ולא ימות.** למדנו מזה שהוא ראוי שיהיה בקטרת מה שיעלה עשן באופן שיהיה עשן הקטרת מוחש והוא הנקרא מעלה עשן והיה נכנס בסמני הקטרת ואם לא היה זה הסם שם יתחייב מיתה. והוא מבואר שאין ראוי שיכניס שם קטרת זרה. ר"ל שלא תהיה במתכונת קטרת הסמי' שאם הכניסה שם הנה נכנס שלא לצורך עבודה ויתחייב מיתה כמו שקדם והנה ישאר שם הכהן עד שיעלה ענן הקטרת וכסה את הכפרת ואחר כך יצא משם וראוי שיהיו פניו לצד המערב גם בצאתו כי אין ראוי שיהיה אחוריו אל ארוך יי' וזה מבואר בנפשו כל שכן מה שנראה שדקדקה התורה בכל הנעשה שיהיה לפני יי':
@14 **ולקח מדם הפר והזה באצבעו על פני הכפרת קדמה ולפני הכפר' יזה שבע פעמים מן הדם באצבעו.** לפי שהכפרת פנים לצד המזרח ולצד צפון ולצד דרום הנה זכרה התורה שתהיה זאת ההזאה אצל פני הכפרת לצד מזרח שהוא כנגד פני הכהן כשיהיה פניו אל הארון והנה מלבד זאת ההזאה שהיא על פני הכפרת יזה לפני הכפרת שבע פעמים וגו' כמו שנתבאר בהזאות הדומות לזה במה שקדם ואמנם קצרה התורה בזה והנה תהיה ההזאה הראשונה למעלה והשבע למטה לפי שנאמר על הכפרת ושאר הזאות הם לפני הכפרת והוא מבואר ממה שקדם שאלו ההזאות יחוייב שיהיו באצבעו הימנית:
@15 **והמשלח את השעיר לעזאזל וגומר.** ראוי שתדע שלא יקרא משלח עד שיצא מהעיר שבית המקדש בתוכה כאלו תאמר חוץ מירושלים כי כל זמן שהוא בעיר הוא במה שממנו התנועה כי העיר הוא הפך המדבר שאליו התנועה ובצאתו מהעיר והוא בדרך אז החל בתנועה הזאת ואז יקרא משלח ומן אז יטמא בגדים שעליו ולא יטמא הנוגע בשעיר הזה אבל יטמא משלחו מצד מה שהוא משלחו אף על פי שלא נגע בו וראוי שיתבאר מזה שהמוציא פר ושעיר הנשרפין מחוץ למחנה הוא טמא ומטמא בגדים כי הוא ראוי בזה כמו שמשלח שעיר המשתלח כי הם נשרפין חוץ למחנה מפני שאתם העונות כמו שישתלח השעיר מפני שאתו העונות ועוד שהרי מצינו בהם שהשורף אותם טעון כבוס בגדים ולזה ראוי שנלמד מזה כי הם יטמאו מוציאם כמו שעיר המשתלח שיטמא משלחו שאם לא יטמאו אלא השורפם לא היה ראוי בשעיר המשתלח שיטמא כי אם מי שידחפנו להמיתו ולא יטמא בגדים קודם זה:
@16 **וכפר על הקדש מטמאות בני ישראל ומפשעיהם לכל חטאתם.** יקרא קדש מקום הקדשים ואמר שבאלו ההזאות יכפר עליו מטמאות בני ישראל בענין מקדש וקדשיו אם נכנסו במקדש בטומאה או אכלו קדשים בטומאה. ומפשעיהם לכל חטאות הטמאה שהם אלו שזכרנו והנה הפשע יאמר על מה שהוא בזדון וזה מבואר מצד הוראת הגדר ולזה יכפר על זדון טומאת מקדש וקדשיו בזה האופן בפר כהן גדול ושעיר הנעשה בפנים ר"ל שבפר כהן גדול יכפר עליו ועל ביתו ועל הכהנים ובשעיר הנעשה בפנים יכפר על כל ישראל. והנה יכפרו אלו הקרבנות החמורות שבעבירות אלו הטמאות וראוי שתשלם הכפרה בכל מיני עבירות אלו הטמאות כי מן השקר שתשגיח התורה בכפרת קצת מיניהם ולא תשגיח בשאר וזה שקרבן עולה ויורד יכפר על טמאת מקדש וקדשיו כשהית' שם ידיעה בתחילה ובסוף והעלם בנתים כמו שיתבאר בפרשת ויקרא ופר ושעיר הנעשה בפנים ביום הכיפורים מכפר על זדון אלו הטמאות וישאר מאלו העברות מה שאין בו ידיעה לא בתחלה ולא בסוף ומה שיש בו ידיעה בסוף ולא בתחלה ומה שיש בו ידיעה בתחלה ולא בסוף וכבר מצאנו כפרת אלו הטמאות בשעיר ביותר חמור שבמיניהם ולזה כשמצאנו שעירים באים לכפרה ולא נתבאר מה יכפרו הנה יתבאר שהם באים לכפר על דבר שהוא מסוג מה שיכפר עליו זה השעיר וכל שכן שיתבאר זה בשעיר חטאת הנעשה במזבח העולה ביום הכפורים שנאמר בו בפרשת פינחס ושעיר חטאת אחד לכפר עליכם מלבד חטאת הכיפורים למדנו שהוא מכפר על דבר הוא מסוג מה שיכפר עליו חטאת הכפורים והנה ראוי שיכפר על דבר שהוא יותר קל מזדון הטמאה כי ראשונה ראוי שיתנקה מהדבר החמור ואחר כן מהקל וזה מבואר במעט עיון ממה שקדם בענין הקרבנות. וכבר מצאנו עוד בראשי חדשים וברגלים שעירי חטאות ונאמר בהם שהם לכפר כמו שנזכר בפרשת פינחס וראוי שיהיו מכפרים הקל שבמיני אלו הטמאות כי החמור יכפר עליו ביום הכיפורים ולזה יכפר השעיר הבא אחריו על החמור שבמינים הנשארים ולזה יכפרו שעירי ראשי חדשים ושעירי הרגלים על שגגת הטומאות במקדש וקדשיו שאין בהם ידיעה לא בתחלה ולא בסוף ויכפר שעיר הנעשה בחוץ ביום הכפורים על היותר חמור מזה שלא יבא בשום פנים לחייב קרבן עולה ויורד והוא מה שאין בו ידיעה בתחלה ויש בו ידיעה בסוף והנשאר מהעברת אלו הטמאות הוא מה שיש לו ידיעה בתחלה ואין בו ידיעה בסוף וזהו אפשר על חיוב קרבן עולה ויורד וזה יהיה כשתתחדש לו הידיעה במה ששגג בו ואין בכאן כי אם אחד משעירי יום הכיפורי' לכפר עליו על זאת הטומאה כל זמן שלא תתחדש לו ידיעה בה וראוי שתיוחס זאת הכפרה לשעיר הנעשה בפנים לפי שהוא היותר חזק לכפר על הטמאות ולזה יכפר על זדון הטומאה ולפי שהחמור שבמיני השגגות אחר המין שיתחייב עליו קרבן עולה ויורד הוא מה שיש בו כח על שיתחייב עליו קרבן עולה ויורד הנה תיוחס זאת הכפרה לשעיר הנעשה בפנים ולא ייחדה התורה שעיר בכפרת זה המין מהטומאה לפי שזאת הכפרה אינה שלמה כי כל זמן שתתחדש לו ידיעה בסוף על שגגתו יתחייב קרבן עולה ויורד מה שאין כן בשאר הכפרות הבאות על הטמאות שייחדה התורה בהם שעיר:
@16 **וכן יעשה לאהל מועד השוכן אתם בתוך טמאתם.** ר"ל שיזה בו מדם הפר ח' הזאות אחרות כמשפט הנזכר ומדם השעיר שמנה הזאות אחרות כמשפט הנזכר ותהיינה אלו ההזאות לכפר על אהל מעד מאלו הטמאות הנזכרות ולזה אמר השוכן אתם בתוך טמאתם והנה לא בארה התורה באי זה מקום מאהל מעד תהיינה אלו ההזאות. והנה יתבאר זה ממה שזכרה בהזאות הנעשות פנים וזה שהם היו לצד המערבי ממנו באופן שתהיה ההזאה לפני יי' ובזה האופן תהיה ההזאה באהל מועד על פני הפרכת קדמה ולפני הפרכת במה שהיה ממנו כנגד הארון כדי שיהיו פני המזה לפני יי' וכזה תמצא זה מבואר בהזאות הנעשו' באהל מועד שהם בפני הפרכת בפרשת ויקרא:
@17 **וכל אדם לא יהיה באהל מועד לכפר בקדש עד צאתו.** ר"ל שבהזאתו לפני לפנים על הכפרת ולפני הכפרת יחוייב שלא יהיה אדם באהל מועד ומזה המקום יתבאר שבהיותו מכפר על אהל מועד ראוי שלא יהיה אדם בין המזבח ואהל מועד כי היחס אחד:
@17 **וכפר בעדו ובעד ביתו ובעד כל קהל ישראל.** רוצה לומר שיכפר מהטמאות הנזכרות באהל מועד בעדו ובעד הכהנים ובעד כל קהל ישראל. ואמנם הכפרה בעדו ובעד הכהנים תהיה בדם הפר והכפרה בעד כל קהל ישראל תהיה בדם השעיר:
@18 **ויצא אל המזבח אשר לפני יי'.** רוצה לומר המזבח היותר מערבי כי הוא לפני יי' והוא מזבח הקטרת הסמים והנה הכפרה הזאת היא גם כן מהטמאות הנזכרות והיא תהיה כשיזו עליו מדם הפר והשעיר באופן שיזכר אחר זה:
@18 **ולקח מדם הפר ומדם השעיר ונתן על קרנות המזבח סביב.** רוצה לומר כשיטבול אצבעו בדם ויתן ממנו בכל קרן וקרן מקרנות המזבח באופן הנזכר בחטאת וזה יהיה כשיערב דם הפר ודם השעיר ויטבול אצבעו בדם המעורב והנה יתחיל להזות על קרן שנפגע בו תחלה בהכנסו לאהל עם הדם המעורב כמו שהתבאר מהשרשים הכוללים ולפי שבהכנסו שם ילך תחלה סביב המזבח לפאת ימין הנה הקרן שיפגע בו תחלה הוא המזרחי הצפוני ואחריו המערבי הצפוני ואחריו הדרומי המערבי ואחריו הדרומי המזרחי והנה נתן הסבה בכל זה אחר שהשלמנו באור דברי זאת הפרשה:
@19 **והזה עליו מן הדם באצבעו שבע פעמים.** הנה זה יהיה בשטח המזבח העליון במקום הקטרת הקטרת והנה לא פרשנו מלת עליו אצלו כשתהיה ההזאה בקירות המזבח כי לא היו במזבח הזהב שני מקומות אחד למעלה ואחד למטה כמו העניין במזבח העולה ועוד שאף על פי שיהיה שם מקום שני מורה על הצורה כמו העניין במזבח העולה הנה לא תהיה ההזאה בו שבע פעמים להורות על הצורה אבל תהיה ההזאה ברוחב וסביב ולא תהיה באצבעו ולזה הוא מבואר שהכונה באמרו עליו הוא שתהיה ההזאה עליו ממש לא בקירותיו והנה יזה אלו ההזאות ממקום שהשלים שם נתינת הדם על הקרנות והוא הצד הדרומי מזרחי:
@19 **וטהרו וקדשו מטמאת בני ישראל.** רוצה לומר מזדון טמאת מקדש וקדשיו והנה תשלם הכפרה בזה באלו הג' מקומות מאלו הטמאות לכהן גדול ולכהנים ולעם הקהל:
@20 **וכלה מכפר אל הקדש ואת אהל מועד ואת המזבח והקריב את השעיר החי.** רוצה לומר שאחר שישלים כפרת זדון מקדש וקדשיו באלו השלשה מקומות יקריב השעיר החי אשר לעזאזל לפאת מערב מעט להתודות עליו ואחר כך ישלחהו:
@21 **וסמך אהרן את שתי ידיו על ראש השעיר החי.** הנה למדנו בזה המקום שהסמיכה היא בשתי ידים על ראש הקרבן ומזה המקום נלמד שתהיה הסמיכה בכל כחו כי לזאת הסבה הקפידה התורה שתהיה הסמיכה בשתי ידיו:
@21 **והתודה עליו את כל עונות בני ישראל וגו'.** רוצה לומר שהוא כאלו יסיר עונות ישראל:
@21 **ומפשעיהם לכל חטאתם.** איזה שיהיו עשה או לא תעשה קלים או חמורים וישימם על ראש השעיר בסמיכתו זאת ויתבאר מלשון הכתוב שהוא יתחיל מהקל ויסיים בחמור ולזה זכרה התורה הפשע אחר העון כי הפשע הוא יותר חמור כי הוא מורה על הזדונות כמו שקדם ולפי שהחטא יאמר על היותר קל כמו שהתבאר בפרשת ויקרא שהחטא יאמר על השגגה אף על פי שלא הודע לו חטאתו אשר חטא הנה יהיה לשון זה הודוי שחטאו ושעוו ושפשעו בני ישראל ויבקש מדבריו מהשם יתע' שיכפר להם זה כי זהו ענין הודוי והנה תלמד גם כן שההדרגה הוא בזה התואר ממה שאמר חטאנו עם אבותינו העוינו והרשענו וראוי שלא יעלם ממנו שהוא ראוי שישובו ישראל בכל לבם לשם יתע' ואז יתכפרו להם כל החטאי' בזה הקרבן וזה שאם דקדקה התורה בזה בקרבנות יחיד הבאות על השגגות כל שכן שתקפיד בזאת הכפרה הנפלאה אשר באה להניח חטאים גדולים ולזאת הסבה היתה התרועה בר"ח השביעי כמו שיתבאר במה שיבא בג"ה ומזה המקום למדנו שהודוי הנעשה על פר כהן גדול הוא גם כן בזה הענין כי פר כהן גדול הוא לו ולכהנים תמורת שני שעירי העזים לכל ישראל שנאמ' בזאת יבא אהרן אל הקדש בפר בן בקר לחטאת ואיל לעולה. ומאת עדת בני ישראל יקח שני שעירי עזים לחטאת ואיל אחד לעולה. והנה אחד מהשעירים יכפר על זדון טמאת מקדש וקדשיו והשני יכפר על כל עבירות שבתורה והוא המשתלח והנה על שני אלו הדברים יכפר כהן גדול בעדו ובעד הכהנים ולזה יהיה לשון הודוי הראשון שחטא ושעוה ושפשע הוא וביתו שיכפר לו השם יתע' ולשון הודוי השני הוא שחטא ושעוה ושפשע הוא וביתו והכהנים ושיתפלל להשם יתע' שיכפר להם זה:
@21 **ושלח אותו ביד איש עתי המדברה.** רוצה לומר איש של רוב הרגלו בהליכה במדברות לא ימתין אכל כל עת הוא נכון לו כאלו הוא בעל העת כי יש אנשים רכי הלב ואולי ילכו שם בעת אחת לא בעת אחר ליראתם מן ההליכה בכמו אלו המקומות כל שכן אם יקרו דברים מונעים כמו המטר ונשיבה הרוחות החזקות ומה שידמה לזה ולפי שהכפרה לא תשלם בזולת שלוח זה השעיר למדבר היה ראוי שידקדקו שיהיה המשתלח איש עתי שיהיה כל עת נכון לו באופן שישלים מה שכוון לזה ובזה לא דקדקה התורה במשלח שיהיה כהן ולזה יהיה שלוח השעיר אפילו בישראל:
@22 **ונשא השעיר עליו את כל עונותם אל ארץ גזרה.** רוצה לומר אל ארץ שלא יעבד בה ולא יזרע והנה בזה תועלת לישב בלבם שכבר נתכפרו להם עונותיהם ולא יתרשלו מעבוד השם יתע' מפני מה שהפליגו לחטא במה שקדם. וראוי שנדע שזה השעיר ימות שם בשלוחו אותו וזה יתבאר מפני' שונים מהם שאם היה שלוחו להניחו חי כמו העניין בשלוח הצפו' החיה של מצורע הנה מפני שזה השעיר הוא חטאת יקרה בו מהתקלה הרבה. ועוד שאם דקדקה התורה במקום שישלחהו בו שלא יהיה בו תועלת לבני אדם כל שכן שתדקדק מה בשעיר בעצמו ולזה יחוייב שיהיה שלוחו לעזאזל באופן שימות. וזה יהיה כשידחהו המשלח שם משן הסלע גבוה כי זה יורה עליו לשון עזאזל מצד הוראת הגדר. ולזאת הסבה היה המשלח טעון כבוס בגדים כמו שטעון כבוס בגדים השורף פר ושעיר וזה כי השעיר החי לא יטמא מצד מה שהוא חי אבל יטמא משלחו מצד ששלוחו להמיתו והנה כמו שהיה תכף לסמיכה שחיטה בקרבנות כן יהיה תכף הסמיכה שלוח בזה השעיר מפני שסופו אל ההמתה:
@22 **ושלח את השעיר במדבר.** רוצה לומ' שכיון שיתברר שישתלח השעיר במדבר אף על פי שלא הגיע עדין למקו' הגבוה שידחפהו משם משלחו להמיתו יעשה הכהן גדול אלו הפעולות שיזכור אחר זה. וראוי שתדע שהמשלח אם לא יכול להשלים השלוח בזולת אכילה הנה יותר לו אז לאכול כי זה הוא מצורך השלוח אשר יחוייב שיעשה ביום הכיפורים וזה מבואר בנפשו:
@23 **ובא אהרן אל אהן מועד ופשט את בגדי הבד אשר לבש בבואו אל הקדש.** ראוי שנדע שלא חייבה אותו התורה לבא אל אהל מועד לפשוט בגדיו שם כי זה בלתי ראוי במקו' הנכבד ההוא רוצה לומ' שיעמוד שם ערום וכ"ש שזה יותר נמנע מצד שימשך לזה שיצא כהן גדול ערום משם וילך ערום אל הלשכה אשר בה המקוה אשר יטבול בו לא צותה התורה גם כן שיבא שם שלא לצורך כי כבר הוזהר מזה במה שקדם ולזה יחוייב שתהיה זאת הביאור לצורך ויחוייב עם זה שתהיה באופן שיחוייב העשותה בבגדי לבן כי לא זכרה התורה שנותו בגדי לבן לבגדי זהב עד אחר זאת הביאה ומזה המקו' יתבאר שזאת הביאה היא להכנס לפני לפנים להוציא הכף והמחת' כי לא נשאר מעבודת יום הכיפורים דבר יהיה ראוי שיעשה בבגדי לבן זולת זה כי אין ראוי שיכנס לפני לפני' בבגדי זהב כמו שקדם ולפי שאין רשאוי שיוציא משם הכף והמחתה טרם השלם העיכול לקטרת ולאש אשר במחתה והיה זה ממה שלא יתאמת שישלם בכמו זה העת הנה יצטרך להמתין לסלק הכף והמחתה עד הערב וראוי שיהיה זה בעת שיצטרך לבא אל אהל מועד להקטיר קטרת הסמים ולהעלות את הנרו קודם שיקטיר קטרת הסמים ויעלה את הנרות כדי שלא יהיה ענן הקטרת לפנים מאהל מועד ולפי לפנים יחד כי ההערה בו באלו השני מקומות קרובה להיות אחת כמו שנבאר ולזה אין ראוי שתהיה בשני המקומות ובכלל הנה אז ישלם בלי ספק העיכול לאש ולקטרת ואין ראוי שיכנס שם הכהן אם לא אחר שיתברר לו שישלם זה כדי שלא יכנס שם שלא לצורך ויתחייב מיתה בידי שמים והנה לא זכרה התורה בביאור סלוק הכף והמחתה לפי שאינו מכוון בעצמו ואינו מצורך הכפרה אבל בהכרח יתחייב לכבוד המקום ההוא שלא ישאר שם האפר בכל השנה עד בא יום הכיפורים אחר שיסירה משם הכהן הגדול בבואו לכפר בקדש והנה לא נזכרה בזה המקום זאת הביאה כי אם להשלים זכרון הדברים שיעשו בבגדי לבן לא שיהיה סדר העניין כן ואולם שאר הדברים כלם נזכרו על הסדר אשר אם נשתנה הסדר ההוא לא יהיה במה שיעשה בזולת סדרו תועלת והנה יפשוט כהן גדול בגדי לבן בלשכה שיטבול בה ושם ילבש בגדי זהב:
@23 **והניחם שם.** רוצה לומר שלא ישמש בהם עוד ומזה יתבאר שהם אסורים בהנאה והנה יתבאר טעם זה אחר השלימנו באור זאת הפרשה. וראוי שתדע כי אח שלוחו השעיר יוציא אמורי פר ושעיר להקטירם על המזבח העולה ואחר שיתבאר לו שהגיע השעיר למדבר ישלח פר ושעיר מחוץ למחנה לשרפם וינתחם באופן שהתבאר בפר כהן משיח בפרשת ויקרא ולזאת הסבה אמרה תורה ושלח את השעיר במדבר ולא הוצרכה להזכיר הוצאה חלבי החטאת כי זה מבואר ממה שקדם מענין הקרבנות והנה סמך אחר זה שלוח השעיר לעזאזל להוצאת פר ושעיר מחוץ למחנה לשרפם להעיר שזה היה נעשה יחד והנה העניין מעמו יעיר על זה כי הפר של כהן גדול היה נכלל בו. כל עניין שני השעירים ולזה ראוי שיהיה ענין השעירים נעשה יחד כמו העניין בפר שהוא גוף אחד:
@24 **ורחץ את בשרו במים במקו' קדוש.** ר"ל באחת הלשכות אשר בעזרה ומזה המקום נלמד שכל עת שיטבול ביום הזה להחליף בגדים מבגדי לבן לבגדי זהב או הפך יהיה טעון טבילה בקדש וראוי שיתבאר מזה ג"כ שבלבשו בבקר בגדי זהב לעבוד עבודת תמיד של שחר והמוספין יצטרך טבילה וזה שבהכנס לעבודה יצטרך כל כהן קדוש ידי' ורגלי' ולט יצטרך לזה בשאר העבודות שיעבוד ביום ההוא כמו שקדם ואם במקום שאין טעון קדוש ידי' ורגלי' חייבתהו התורה לטבול כ"ש שיתחייב לטבול במקו' אשר הוא טעון קדוש ידים ורגלי' ולזה יתבאר גם כן שבכל טבילה יהיה קדוש ידי' ורגלי' כל שכן במקו' שנתחייב טבילה והנה נבאר הסבה בכל זה במה שיבא:
@24 **ולבש את בגדיו.** ר"ל בגדי זהב כי הם בגדיו אשר יעבוד בהם תמיד:
@24 **ויצא ועשה את עולתו ואת עולת העם.** רוצה לומר אילו ואיל העם והנה יעשה תחלה עולתו ואחר כך עולת העם כמו הענין בחטאת והיה זה למעלת הכהן עם שאין ראוי שיכפר על זולתו קודם שיכפר על עצמו מה שלו מהחטאים ההם ולפי ששם שעיר החטאת אחד להשלי' זאת הכפרה כמו שנזכר בפרשת פינחס הנה ראוי שיהיה נעשה קודם עולתו ועולת העם כי החטאת קודם לעולה כמו שיתבאר במה שקדם. ואמנם לא הזכיר זה בזה המקום כי לא נזכר בזה המקום החטאת ההוא. וראוי שתדע כי האיל שנזכר בפרשת פינחס בעולה שיקריבו בני ישראל ביום הכפורים הוא האיל הזה שקרא איל העם. וזה שכבר אמר שם ושעיר עזים אחד לחטאת מלבד חטאת הכפורים ועולת התמיד למדנו מזה שכל העולות והחטאות באות משל צבור ביום הכפורים נזכרו שם מלבד חטאת הכפורים ועולת התמיד של שחר ושל בין הערבים ולזה הוא מבואר שכבר נזכר שם איל העם והוא האיל הנזכר:
@24 **וכפר בעדו ובעד העם.** רוצה לומר שבה תשלם הכפרה בשלמו' כי הקרבת העולה הוא להעיר שכבר נשלם הרצוי במה שהתבאר במה שקדם:
@25 **ואת חלב החטאת יקטיר המזבחה.** רוצה לומר אחר הקרבתו עולתו ועולת העם יקטיר אמורי פר ושעיר הנשרפין על המזבח העולה:
@26 **ורחץ את בשרו במים.** רוצה לומר אחר שיטבול ויעריב שמשו יוכל לבא אל המחנה שיצא ממנו והוא העזרה ואפשר שנמנעה ממנו הביאה אל המחנה אפי' תוך חומת ירושלם ביום ההוא קודם שיטבול להעיר על התחזק מהעונו' אשר נשאום אלו החטאות:
@26 **ואחר יבא אל המחנה.** ראוי שתדע שלא תדחה ביאתו אל המחנה יום הכפורים שהוא אסור במלאכה והנה הרצון בזה שאחר כן יוכל לבא אל המחנה ולהכנס למקדש אחר שיעריב השמש:
@27 **ואת פר החטאת וגומר והשורף אותם יכבס בגדיו.** מפני שאמרה התורה בזה המקום אשר הובא את קדמם לכפר בקדש ולא היה צרך זה בזה המקום לפי שכבר ידענו זה למדנו שהשורף טעון כבוס בגדים מפני שהובא את דמם לכפר בקדש ולזה יתבאר שכל חטאות הנשרפות מחוץ לחנה מטמאות בגדי שורפם וכן הענין בבגדי מוציאם מחוץ למחנה ובכלל הנה לסבה אשר התחייב בזה המקום יתחייב זה בכל חטאות הנשרפות וראוי שתדע שכבר יתואר שהוא מוציא מחוץ למחנה תכף שיצא מן המחנה שהוא בו כי כל עוד שהוא במחנה ההוא בעינו הוא כמה שממנו התנועה ולזה לא יקרא מוציא חוץ למחנה עד שיצא חוץ לעזרה וכן משהיגע למקום שריפתו אינו מטמא המתעסק בו כי לפי מה שאחשוב אלא אם היה מתעסק בשריפתו. והשורף מטמא בגדים כל זמן שיהיה אפשר שיתואר כשהוא שורף ולזה יטמא בגדים המתעסק בשריפתו עד שתשלם השרפה ויעשה האפר והוא מבואר שלא יקרא שורף מפני הבעירו האש אם לא היה באש הזה זה החטאת הנשרף:
@28 **ורחץ את בשרו במים.** רוצה לומר אחר שיטבול ויעריב שמשו יוכל לבא אל המחנה שיצא ממנו והוא העזרה ואפשר שנמנעה ממנו הביאה אל המחנה אפי' תוך חומת ירושלם ביום ההוא קודם שיטבול להעיר על התחזק מהעונו' אשר נשאום אלו החטאות:
@29 **והיתה לכם לחקת עולם.** רוצה לומר זאת העבודה שקדם זכרה:
@29 **בחדש השביעי בעשור לחדש תענו את נפשותיכם וכל מלאכה וגומר.** הרצון בזה הענוי שלא יאכלו ושלא ישתו וזה מבואר מצד הוראת הגדר ומעצם הענין וזה שכבר יראה שהיתה הכונה בזה שיבדלו מאלו ההנאות למען יכנע לבבם ויתנו אל לבם לשוב מדרכם הרעה כי זה כיון ביום הזה כדי שתשלם להם הכפרה ולזאת הסבה היתה התרועה בראש השנה כמו שיתבאר במה שיבא בגזרת הצור. ולפי שהוציאה התורה זה בלשון ענוי ולא אמרה בביאור שלא יאכלו בעצם היום הזה הנה לא יעברו על זאת המצו' באכילת כזית אבל באכילה שמצדה ימנע העינוי ושערו חכמים שזה ישלם בשיעור מהמזון בכותבת הגסה לא בפחות מזה ובשתייה ישלם זה בשיעור רביעית לוג לא בפחות מזה וראוי שיתבאר מזה שאם אכל אוכל בלתי ראוי לאכילה או שתה משקה בלתי ראוי לשתי' לא יענש על זאת הצואה כי אין זה ממה שיעבור הענוי בסבתו אבל הוא ענוי וכן אם אכל על השבע המופלג והנה נאסר בכל מלאכה כמו הענין בשבת:
@29 **האזרח והגר הגר בתוככם.** ר"ל בגר צדק ולמדנו בזה שלא נקבל גר צדק לחציין אם לא יקבל עליו כל התורה כולה:
@30 **כי ביום הזה יכפר עליכם תטהר אתכם.** למדנו שהיום הזה מכפר אע"פ שאין שם בית המקדש לעשות העבודה הנזכרת והיה זה כן מפני שנתנה התורה סבת המצות הנהוגות בפני הבית ושלא בפני הבית היות השם יתעלה מכפר ביום הזה מכל חטאות ישראל והיה זה כן לפי שעיקר הכפרה היא התשובה והצום עם השביתה מהמלאכה ומכל צרכי הגוף מעיר על התשובה הערה נפלאה:
@30 **מכל חטאתיכם לפני יי' תטהרו.** ר"ל שכבר יטהרו מכל חטאתם לפני יי' בזאת העבודה הנעשת בבית המקדש לפני ה' או ירצה בזה שהם יטהרו לפני י' בשובם אליו בזה האופן ויהיו במדרגת מי שלא חטא:
@31 **שבת שבתון היא לכם.** זאת היא מצות עשה לשבות בו מכל מלאכה:
@31 **ועניתם את נפשותיכם חקת עלם.** הנה שתי אלו המצות לפי שאין להם התלות בבית המקדש הוא מבואר מעניינם שהם נוהגות תמיד:
@32 **וכפר הכהן אשר ימשח אותו.** ר"ל שזאת הכפרה הנעשת בבית המקדש תעשה על יד כהן משיח בשמן המשחה או ע"י כהן אשר ימלא את ידו לכהן תחת אביו אף על פי שאינו משוח בשמן המשחה והוא המרובה בגדים ולמדנו מזה שבזמן שבן כהן גדול ראוי לכהונה גדולה הוא קודם לכל אדם ומבואר זה בנפשו כמו שביארנו במה שקדם:
@32 **ולבש את בגדי הבד בגדי הקדש.** למדנו מזה שהדבר המתיחס לכפרת היום יעשהו כהן גדול בבגדי לבן:
@33 **וכפר את מקדש הקדש ואת אהל מועד וגו'.** למדנו שלכל אחד מהם כפרה בפני עצמה ולזה לא תעכב כפרה המתאחר כפרת הקודם. ואולם כפרת הקודם תעכב כפרת המתאחר כדי שלא ישתנה הסדור שסדרה התורה בזה:
@33 **ועל הכהנים ועל כל עם הקהל יכפר.** כבר התבאר מזה מה שאמרה שנית וכפר בעדו ובעד ביתו ירמוז בו אל הכהנים כי הם בניו כמו שביארנו:
@34 **והיתה זאת לכם לחקת עולם לכפר על בני ישראל מכל חטאתם אחת בשנה.** ר"ל שתעשה העבודה הזאת בזה האופן ובסדור הנזכר פעם אחת בשנה והיא בעשור לחדש השביעי:
@34 **ויעש כאשר צוה יי' את משה.** הורה בזה שכל זה מכוון באופן הנזכר ולזה לא הפיל אהרן ממנו דבר הנה זהו ביאור דברי זאת הפרשה:
@36 **דבר אל אהרן ואל בניו ואל כל בני ישראל.** ראוי שתדע כי הגר הוא בכלל כי כבר זכרה התור' בביאור במה שדומה לזה בזאת הפרש' עם שזה מבואר בכללות שמשפטי התורה הם שוים לגר ולאזרח הארץ:
@37 **איש איש מבית ישראל אשר ישחט שור או כבש או עז במחנה.** זכר שור וכבש ועז לפי שמהם יהיו הקרבנות כמו שנזכר בפרשת ויקרא ואמר במחנה ר"ל במחנה ישראל וגומ':
@38 **ואל פתח אהל מועד וגו'.** רוצה לומר מחוץ למחנה ישראל והנה הוא מדבר בקדשים ששחטם חוץ לעזרה היה ששחטם במחנה ישראל או ששחטם חוץ למחנ ישראל כדי שלא הביאו לשחטו אל אהל מועד באופן שצותה התורה כדי שיהיה נאות להקריב קרבן להש' לפני משכן ה' הנה הדם ששפך בזאת השחיטה יחשב לו דם ר"ל שכבר יתחייב עליו מיתה ולזה ביארה התורה שכבר יתחייב עליו כרת והנה התבאר מזה המקום שבקדשים ידבר כי הם ראוים להביא אל אהל מועד ולזה ראוי שיהיו הקדשים ראוים לבא אל אהל מועד ואז יתחיי' כרת על שחיטתן בחוץ. אבל אם היו בעלי מומין או שהיו באופן מה זולת זה שאינן ראויים לבא אל אהל מועד הנה לא יתחייב כרת על שחיטתן וראוי שיתבאר מזה המקום כי הנשחט בחוץ הוא פסול להקריב ממנו קרבן לה' כמו שהתבאר מדברנו בביאור זה הפסוק וראוי שלא יעלם ממנו כי התורה תדבר במה שהיא שחוטה במחנה או מחוץ למחנה רוצה לומר שהוא בגדר השחיטה שם ולזה אם שחט בלילה שם הנה אם תהיה שחיטתו שחיטה כי בשחיטה אשר שם לא יהיו מתנאיה שלא תהיה בלילה כמו העניין בשחיטה אשר בעזרה שאינה אלא ביום כמו שהתבאר ולזאת הסבה לא יתחייב המולק את העוף חוץ לעזרה כי אין זה העניין נכנס בגדר השחיטה חוץ לעזרה אבל ידמה שם זה הענין לנהירה או לנדמה לה ולזה יתחייב על שחיטת עוף שהוא קדשי' בחוץ כיון שלא הביאו אל אהל מועד באופן הראוי להקריב ממנו קרבן להשם:
@39 **למען אשר יביאו בני ישראל את זבחיהם אשר הם זובחים על פני השדה והביאום לה' אל פתח אהל מועד אל הכהן.** קרא על פני השדה מה שהוא חוץ מהמקום המוגבל לזבחי השם יתעלה כי השדה מורה על זאת הכונה כמו שביארנו בפסוק אמרו ובשר בשדה טרפה לא תאכלו עם שכבר היה אפשר שהיו ישראל קודם מתן תורה זובחים זבחים על פני השדה לא לעבודה לשם יתע' הלא תראה במעשה העגל שהעלו עולות ויגישו שלי' והיה זה המנהג הפחות להם ממה שנהגו וגדלו עליהם בהיותם במצרים בדעותיהם הנפסדות ומנהגיהם הפחותים וזבחו זבחי שלמים להשם אותם:
@40 **וזרק הכהן את הדם.** ר"ל שאפילו השלמים נאכלים לבעלים והיה אפשר מפני זה שיחשב שלא יתחייב כרת אם ישחטום בחוץ מפני חלק הבעלים שהוא נאכל במחנה ישראל הנה יחוייב שיביאום אל אהל מועד לשחטם כדי שיהיו להש' ויקריב מהן למזבח הדם והחלבי':
@41 **ולא יזבחו עוד את זבחיהם לשעירים.** ר"ל לשדים והם הדמיונים הכוזבים שיביאום לחשוב במה שאיננו אלוה שהוא אלוה ואחשוב כי מפני ששבתי הוא אשר ייוחס לו עניין השדים כמו שהתבאר במשפטי הכוכבים והיה גדי בית שבתאי הנה נקראו השדים שעירים ואע"פ שדלי גם כן הוא בית שבתאי הנה יתחדשו הדמוינים המפסידים משבתאי מצד טבע השחורה אשר מזל גדי מתיחס לו וכן העניין בשבתאי לא מצד טבע הדם אשר מזל דלי מתיחס לו:
@41 **חקת עולם תהיה זאת לכם לדורותיכם.** ראוי שנדע שזאת החקה הנוהגת לדורות בזה הענין הוא שלא לזבוח לשעירים וכ"ש לע"ז ואמנם השחיטה חוץ מפתח אהל מועד לא יתחייבו עליה כרת כי אם אחר שנגלה להם המקום שנבנה בו המזבח בהר המוריה כי קודם זה היה אפשר להם לשחוט ולהעלות הקרבנות לשם יתעלה בכל המקומות כמו שיתבאר בפרשת ראה אנכי ולפי זה הפירוש יהיה זה מצות לא תעשה והנה הרב המורה לא מנאה ובספרא אמרו והביאום להשם מצות עשה מצות לא תעשה מנין ת"ל ולא יזבחו עוד את זבחיהם לשעירים והנה אפשר שיהיה הרצון בזה כי לולי הבאתם הקרבנות לה' אל אהל מועד יהיה סבה שלא יזבחו עוד את זבחיהם לשעירי' וזה שאם היה מותר להם לזבח לש"י מכל מקום הנה יהיה זה סבה שלא יעמדו על אמתת השם ויחשבו בו רבוי לזאת הסבה על שלמעוט עמידתם על האמת בזה תהיה הקרבתם למה שיהיה האלוה לפי הדמיונים הכוזבים שר הם השרים באמת ולפי זה הפירוש יהיה שב אמרו חקת עולם תהיה זאת לכם לדורותיכם לענין שחיטת קדשים בחוץ וזה אמנם יהיה אחר הגלות בית עולמים כמו שיתבאר בפרת ראה אנכי וכבר יורה שאין אמרו ולא יזבחו עוד את זבחיהם לשעירים מצות לא תעשה שאם היה הדבר כן לא היתה בזה המאמר מלת עוד אבל היה המאמר בזה ולא יזבחו את זבחיהם לשעירים ואולם אמר עוד יורה שהרצון בזה שזה יהיה סבה שלא יזבחו עוד שבחיהם לשעירי' וזה מבואר מאד:
@42 **ואליהם תאמר איש איש מבית ישראל ומן הגר אשר יגור בתוכם אשר יעלה עולה או זבח ואל פתח אהל מועד וגו'.** ר"ל שאם יעלה עולה או זבח חוץ לעזרה יתחייב כרת והנה זכר העולה שהיא כלה כליל ואחר כך הזבח שלא יקריבו ממנה לשם כי אם קצתו להעיר שאיך שיהיה העניין בזה יתחייב עליו כרת ובאמרו אל פתח אהל מועד לא יביאנו למדנו שכל הראוי לבא אל אהל מועד אם עשה אותו בחוץ לקרבן באופן שלא יוכל להביאו אל אהל מועד כמשפטו יתחייב כרת והנה אמרנו שיעשה אותו בחוץ לקרבן לפי שנאמר עולה או זבח ומזה המקום יתבאר שנסוך היין אע"פ שלא היה קרב על המזבח אם עשה אותו בחוץ חייב שהוא ראוי להביאו לאהל מועד שנאמר בקדש הסך נסך שכר לה' ויתבאר שאינ חייב כרת אם לא יעשה זה הקרבן להשם יתעלה שנאמר עולה או זבח והעולה והזבח הם לחש' לפי הוראת הגדר וזה מבואר ממה שקדם במעשה העולה והזבח. וראוי שתדע שלא יתחייב על העלאה בחוץ להשם אם לא נבנה שם מזבח כי המזבח לקוח כנגד העלאת הקרבנות ולזה תמצא בנה ואברהם ויצחק ויעקב ובלעם במה שהקריבו מהקרבנו' ליי' בניית המזבח:
@44 **ואיש איש מבית ישראל ומן הגר הגר בתוכם אשר יאכל כל דם.** לפי שזכר אחר זה ואני נתתיו לכם על הזבח למדנו שלא יתחייבו כרת אלא עם הדם אשר מדרכו שינתן על המזבח והוא דם הנפש כמו שאמר דם הפר ודם השעיר ואולם דם התמצית ודם האברים לא יתחייבו עליו כרת ויתב' מהשרשים הכוללים שהדם ההוא הוא באזהרה:
@45 **כי נפש הבשר בדם הוא.** ר"ל שהד' הוא הכלי לנפש להוביל בו החו' היסודי והמזון לחלקי הגוף ולזה ימות הב"ח רק בהסתלק הדם ולזאת הסבה היתה ההערה בו על הנפש כמו שביארנו בעניין הקרבנות והיה מכפר על הנפש בזה האופן וכבר יתבאר במה שקדם שאסור הדם אינו נוהג כי אם בבהמה ובעוף ואולם דם שאר הב"ח לא יתחייבו עליו מזה הדם ולפי שדם הבהמה ועוף אסור והיתה החיה בלתי קרבה להשם יתעלה ולא העוף באופן שיהיה ממנו שלמים חייבה התורה בחיה ובעוף הטהורים כאשר ישחטם שנכסה דמם בעפר כדי שלא יבאו הנשים לאכול דמם ואולם הבהמה לא הוצרכה בה התורה לזה לפי שלא הותר לישראל בתחלה לאכול בשר כי אם שלמים וכבר היה קרב מהם החלב והדם לשם יתעלה ואולם אחר שארך הזמן וסרו ישראל מהמנהגים הפחותים אשר הסתבכו בהם בהיותם במצרים מאכילת הדם והחלב אז הותר להם בשר תאוה כמו שיתבאר במה שיבא והנה אמרה התורה אשר יצוד ציד חיה או עוף לפי שהנהוג בהם שהם נצודים והוא מבואר ממה שביארנו שכבר ינהג זה הדין בהם אע"פ שלא צד אות' הוא בעצמו כאלו תאמר שנתנו לו במתנה או שקנאם וראוי שנדע שלא ינהג זה הדין אלא בחיה ובעוף הטהורים שנאמר אשר יאכל ולפי שלא ביארה התורה אסור חלב בחיה ובעוף כי אם בבהמה במקום שזכרה אסור דם בבהמה ובעוף ר"ל בפרשת צו הנה למדנו מה שאין אסור חלב נוהג בחיה ובעוף וכבר יתבאר מעצם הענין שאין להם חלב אבל הוא שומן מטבע השומן וראוי שנדע שלא ינהגו כסוי הדם כי אם בשחיטה המותרת באכילה שנאמר אשר יאכל ובכלל הנה כאשר לא יותר לאכול מהבשר בסבת השחיטה כ"ש שיתרחקו מלאכול הדם ולזה לא יצטרכו לכסוי הדם כי עם שהוא אפשר ג"כ שהיה ממנהגיהם הפחותים שיצודו חיה או עוף להיותם מדבריים ויחשבו שיהיו השדים מזה הצד יותר מתייחסים להם ולזה היה ממנהגיהם שישפכו דמם במקום אחד והיו אוכלין הבשר סביב הדם ההוא והיו חובים שיבאו שם השדים לאכל הדם כי הוא מזונם לפי מחשבתם ובזה האופן תשלם האהבה להם עם השדים ויודיעו להם העתידות ולזה אמר לא תאכלו על הדם ואחר כן אמר לא תנחשו ולא תעוננו כמו שיתבאר במה שיבא וכבר זכר זה הרב המורה רצוני לומר שכבר היה ממנהגיהם הפחותים לאכול על הדם לזאת סבה כמו שראה בספריהם הקודמים ולזה גם כן לא היה נוהג כסוי הדם בחיה ועוף ולפי שהתכלית היה לאכול הבשר סביב הדם לזאת הסבה שזכרנו הנה כשלא היה הבשר נאכל לא יתחייבו בכסוי וראוי שנדע שצריך שיהיה עפר למעלה ועפר למטה שנאמר ושפך את דמו וכסהו בעפר ר"ל שישפוך את דמו בעפר ויכסהו בעפר והנה בזה האופן גם כן תעמוד התורה כנגד הכונה ההיא וזה שכאשר ישפך הדם לא ימצא שם במורגש אבל יהיה נבלע בעפר והוא מבואר שכל מה שיקרא עפר בלשון קודש יתכן לכסות בו את הדם:
@48 **כי נפש כל בשר דמו בנפשו הוא.** ר"ל שנפש הבשר וחיותו הוא באמצעות הכח אשר בנפשו להזות דמו ולזה יחדו השם יתע' לכפר על הנפש וכדי שיתיישב יותר בלב האנשים שהכפרה תשלם בזה ראוי שיהיה ענינו מרוחק האכילה כי אם יאכלוהו לא יחשבו בו יתרון על הבשר הזה ובכלל הנה השתנות המזון אל הדם הוא מבואר שהוא מפועל הנפש כי אל ימצאו הדברים המזוניים נהפכים לדם עם הפסדם אם לא כשיזון מהם הב"ח ולא היה בזה מופת על מציאו' הנפש כי אין מדרך החום שימשך ממנו זה אם לא היה חום נפשיי ולפי שאלו הדברים היו להעיר על מציאות הצורה כמו שזכרנו במה שקדם הנה הגבילה התורה ענין הדם בזה האופן:
@49 **וכל נפש אשר תאכל נבילה וטרפה.** ראוי שתדע שאין הרצון באמרו נבלה וטרפה נבלה או טרפה כי הטרפה לא תטמא אם לא היתה עם זה נבלה לא הטרפה השחיטה כמו שהתבאר בפרשת ויהי ביום השמיני בב"ח אשר טומאתו יותר חמורה אמר וכי ימות מן הבהמה אשר היא לכם לאכלה למדנו שהשחיטה אינה מטמאה ולזה יהיה הרצון בזה שתהיה נבלה וטרפה יחד ולפי שהיתה טרפה אינו סבת הטמאה ואין לו רושם בה כמו שהתבאר מדברנו מזה המקום הנה לא יהיה התנאי בזאת הטמאה שתהיה טרפה אבל תטמא גם כן בזה האופן אם היתה נבלה לבד וזה מבואר מאד ואמנם זכרה התורה נבלה וטרפה להורות שהיא תדבר במין מהב"ח שאפשר שיהיה בו נבלה וטרפה יחד והוא המין הטהור כי בב"ח הטמאים לא תנהג טרפה ולפי שזאת הנבלה לא נזכר בה שתהיה מטמאה במגע ובמשא אבל תטמא כשתאכל הנה אינה הנבלה המטמאה במגע ובמשא הנזכרת בפרשת ויהי ביום השמיני עם שאם היה העניין כן הנה זה כפל ומותר ולזה הוא מבואר שאין זאת הנבלה אינה נבלת חיה ולפי שהוא זכר בזה המקום החיה והעוף אשר יאכל למדנו שבנבלת עוף טהור מדבר והוא אינו מטמא כי אם בזה האופן בהיותו בבית הבליעה לא קודם זה ולא אחר שירד משם וכבר ביארנו הסבה למה לא יטמא העוף הטהור כי אם בזה האופן בפרשת שמיני וראוי שיתבאר שאם יהיה בבית הבליעה כשיקיא אותו שאינו מטמא כי אין זו נקראת אכילה אבל הוא מקביל לאכילה:
@50 **ואם לא יכבס ובשרו לא ירחץ ונשא עונו.** ר"ל שיתחייב כרת ולפי שאי אפשר שיתחייב כרת על הטמאה אם אכל קדש או נכנס במקדש בהיותו טמא הנה יהיה הרצון בזה שאם יאכל עם זה קודש או יכנס למקדש בהיותו טמא קודם הטהרו מזאת הטמאה יתחייב כרת:
@53 **כמעשה ארץ מצרים אשר ישבתם בה לא תעשו.** הנה ירא' מלשון התורה בזה שמנהגי ארץ מצרים ונימוסיהם בעניין העדיו' היה בתכלית מהגנות וכן הענין במנהג ארץ כנען ונימוסיהן בענין העריות ולזה הזהירם הזם יתעלה שלא ינהגו בכמו אלה המנהגים הפחותים ההם כמו שאמר בסוף זאת הפרשה אל תטמאו בכל אלה כי בכל אלה נטמאו הגוים אשר אני משלח מפניכם:
@55 **אשר יעשה אותם האדם וחי בהם.** ר"ל שמדרך משפטי השם יתעלה וחקותיו שיהיה חיי האדם בהם כי הם מישרים לשלמות הנפש שהוא החיים הנצחיים עם שכבר ימצא בהם תועלת גם כן באלו החיים הגופיים כמו שנתבאר בהרבה מהמצות:
@56 **איש איש אל כל שאר בשרו לא תקרבו לגלות ערוה.** ראוי שתדע שבזאת ההזהרה תועלת במדות ותועלת בעיון אמנם התועלת אשר בעיון בזה היא הערה שאין המבוא אשר בהולדה לזכר ולנקבה בהדרגה אחת ולזה הזהירה התורה שתהיה הנקבה שאר בשר הזכר כי שאר הבשר יחשב היותה מטבע אחר לפי שחצבו מצור אחד וכבר התבאר בטבעיות שיש הבדל נפלא בשה בין הזכר והנקבה והוא שזרע הזכר הוא הפועל בהולדה והנקבה תתן החומר שהוא המתפעל בהולדה ואמנם התועלת אשר במסות בזה זכרו הרב המורה והוא שאלו הנקבות שהם שאר בשר אם היו מותרות לאדם הנה לרב מציאותם אצלו ולחוזק האהבה אשר ביניהם בטבע יקרה שיהיו נשמעות אליו תמיד ויבא אליהן גם בזולת אישות ואע"פ שיהיו לאיש אחר ויגיע מזה הפסד נפלא בדברים הטבעיים המדיניים עם שכבר ישחית עצמו מצד רבוי המשגל וראוי שתדע כי גלוי הערוה ישלם בפתיחת הרחם כי אז יתגלה הנסתר והפתיחה ההיא תשלם בהכנסת העטרה לבד ואעפ"י שלא נגמרה הביאה והנה תמצא במקומות שכונה התורה שתהיה בשכיבה שכבת זרע כמו שתראה בשפחה חרופה בפרשת קדושים אמר ואיש כי ישכב את אשה שכבת זרע ואולם בזה המקום לא זכרה כי אם גלוי ערוה לתוספת הרחקה בזה כי אפילו בתחלת הביאה יתחייב כרת וראוי שתדע שזאת השכיבה תהיה אם כדרך הנקבות אם בזולת דרך הנקבות שהרי אמר בזה העניין ואיש כי ישכב את זכר משכבי אשה להעיר שהמשכב ההוא גם כן משכבי אשה ואם אינו עושה פרי ולפי שגלוי הערוה הוא התחלת הביאה הנה לא יהיה גלוי הערוה אלא במי שתתכן בו הביאה והוא בזכר מבן ט' שנה ויום אחד ומעלה ובנקבה מבת ג' שנים ויום אחד ומעלה כמו שהתבא בשרשים הכוללים ומזה המקום יתבאר שאם גלה ערוה בזולת קושי לא יתחייב כרת כי אין זה הענין התחלת ביאה והוא מבוא מזאת האזהרה שהקרב לאחת מהעריות קריבה המביאה לגלות הערוה עובר בלאו אבל לא יתחייב כרת אם לא גלה ערוה שהרי אמר בסוף הפרשה כל אשר יעשה מכל התועבות ונכרתו הנפשות העושות למדנו שלא נתחייב כרת אם לא עשה מעשה לא על השתדלותו לעשותו ואמנם הזהירה התורה בזה להוסיף הרחקה בזה הענין:
@57 **ערות אביך וערות אמך לא תגלה.** הרצון בערות אב משכב זכור ויתחייב עליו משני צדדין האחד מפני שהוא משכב זכור והשני מפני שהוא ערות אב ואם עשה זה בשוגג יתחייב שני חטאות כי כבר חייב על הזדון כרת כמו שהתבאר אחר זה והרצון בערות אם בין כדרכה בין שלא כדרכה וכן הענין בשאר העריות וכן אם היתה אמו עם זה אשת אביו יתחייב עליה ג' חטאות משום אשת איש ומשום אשת אב ומשום אם כמו שיתבאר במה שיבא אח' זה:
@58 **ערות אשת אביך לא תגלה.** ר"ל אף על פי שאינה אמו והיא נקראת אשת אב משנתארסה ואע"פ שמת האב מן הארוסין יתחייב עליה משום אשת אב ואולם אנוסת אביו ומפותת אביו אינה אסורה לו משום אשת אב כי אינה אשתו:
@59 **ערות אחותך בת אביך או בת אמך מולדת וגומ'.** אחשוב שמולדת בית היא ההולדה ר"ל שתהיה לאשה מאישה ומולדת חוץ היא ההולדה שתהיה לאב ממי שאינה אשתו או ההולדה שתהיה לאם ממי שאינו אישה וביארה התורה שאע"פ שהיא אחותו בזנות או בממזרות בין מן האב בין מן האם יתחייב עליה משום ערוה וזהו מה שלמדנו באמרו או מולדת חוץ:
@60 **ערות בת בנך או בת בתך לא תגלה ערותן כי ערותך הנה.** הנה יתבאר ממה שאמר כי ערותך שכבר יתחייב אם גלה ערות בתו אבל היא יותר ראויה בזה כי היא יותר אמתית בעניין שאר הבשר וזה ממנהג התורה כמו שהתבאר מהשרשים הכוללים:
@61 **ערות בת אשת אביך מולדת אביך.** ר"ל שתהיה נולדת מאביו שאם לא היה הענין כן כבר תהיה מותרת לו אם לא היתה אמו אשת אביו הנזכרת בזה המקום וכבר יתחייב עליה משום בת אביו כשהיתה אשתו ואולם אם היתה בת אנוסת אביו או מפותת אביו לא יתחייב עליה משום בת אביו אבל יתחייב עליה משום אחותו מן האב:
@62 **ערות אחות אביך.** ביאר שאחות האב ואחו' האם הם ג"כ אסורות משום ערוה כי הם שאר אב או אם ערות אחי אביך לא תגלה. ר"ל למשכב זכור ויתחייב עליה משום משכב זכור ומשום ערות אחי האב. אל אשתו לקרב:
@64 **דודתך היא.** ר"ל שלא יקרה אליה לגלות ערוה והוא מבואר מצד הוראת הגדר שלא יקרא אחי האב סתם אלא כשהיה אחיו מן האב לא כשהיה אחיו מן האם ולא מן האב וכבר יתבאר בפרשת יבמה ועוד כי מפני שמנעה אחות אב ואחות אם ימנע אחי אב ולא אחי אם הנה יראה שלא מנע אלא מי שהוא אחי האם מן האב לא מי שהוא אחי האם מן האם ועוד שהוא מבואר שלא תקרא דודתו אשת אחי האב מן האם:
@65 **ערות כלתך לא תגלה אשת בנך היא.** הטעם לפי שהוא ערות הבן הוא שאר בשר:
@66 **וערות שאר אחיך.** הוא לפי שנתן הסבה בזה שהיא ערות אחיו ומצאנו בערות אחותו שהשוה אחותו מאביו לאחותו מאמו. הנה יתבאר שזה הדין ינהג גם כן באשת אחיו מן האם:
@67 **ערות אשה ובתה לא תגלה את בת בנה ואת בת בתה לא תקח לגלות ערותה.** הרצון בזה שיהיה לו אישות עם אחת מהם ולזה אמר לא תקח ומפני האישות ההוא נאסר עליו האחרת מפני שהוא שאר אשתו כמו שאמר שארה הנה זמה הוא וכזה תמצא באחות אשתו שאמרו בה לא תקח להעיר כי מפני נשואי אשתו נאסרה על האחת ובזה תמצא בפרשת קדושים שאמר לשון קיחה בזה הענין אמר האיש אשר יקח את אשה ואת אמה זימה היא ולא תמצא לשון קיחה בשאר העריות ולזה יראה במה שאין ספר בו שתהיה אחד מהן אשתו ולזה אמר בפרשת תבא ארור שוכב עם חותנתו ואין לאומר שיאמר שיקח שתיהן לנשים ואז יתחייב כרת כשיגלה ערו' השנית שאם נתחייב כרת כשגלה ערותה אחר שלקחה לאשה כ"ש שהוא ראוי שתאמר לו כשלא לקחה לאשה ולזה הוא מבואר שאין לו לקוחין כי אם עם אחת מהן ובעבורה נאסרה לו האחרת וזה שאם היתה היא אשתו הנה נתחייב כרת אם יגלה ערות בתה או בת בתה או בת בנה וכן אם היתה בת הבת אשתו הנה תאסר עליו חמותו ואם חמותו ותאסר עליו גם כן אם חמיו לפי שאשתו היא בת בנה ולזה הוא מבואר שהאונס אשה או המפתה אשה לא תאסרנה עליו קרובותיה לפי שאין לו אישות בה:
@68 **ואשה אל אחותה לא תקח לצרר.** ר"ל כשנשא אשה לא ישא אחותה באופן שתהיין צרות זו לזו ויגלה ערותה על ערות אשתו בחייה אמנם אחר מות אשתו תותר לו אחות אשתו מה שאין כן בשאר קרובות אשתו הנזכרות בפסוק הקודם וראוי שנדע שאין הבדל באחות אשתו בין היותה אחותה מן אביו או מאמה שכבר תמצא בפרשת קדושים שנקראת אחות סתם מי שהיא אחות מן האב או מן האם אמר ואיש אשר יקח אחותו בת אביו או בת אמו וגו'. ערות אחותו גלה:
@69 **ואל אשה בנדת טמאתה לא תקרב לגלות ערותה.** הנה זה כולל טמאת היולדת שהרי נאמר בה כימי נדת דותה תטמא וטמאת שבועים כנדתה וטמאת זבח קטנה וזבה גדולה שהרי נאמר כל ימי זוב טמאתה כימי נדת דותה תהיה ויתבאר שכל זמן שלא טבלה ינהג זה האסור לפי שטהרתה תלויה בטבילה לא בימים וזה עם שהוא מבואר בנפשו יתבאר מטמאת נבלת עוף טהור שהוא טמאת ערב ועם זה אמרה התורה בפרשה הקודמת ואם לא יכבס ובשרו לא ירחץ ונשא עונו אף על פי שארך הזמן אחר זה כיון שלא טבל עדין הוא בטמאתו ומזה המקום יתבאר שהבא על אשתו והרגישה שכבר ראתה דם אסור לו להכניס האבר או להוציא כי הכנסה וההוצאה הם גלויי ערוה והם מעניין הביאה ולזה ראוי שיתעכב וישים לבו לדבר אחר עד שיסור קושי האבר ואז יוציאהו כי זה אינו נכנס בגדר גלוי הערוה:
@70 **ואל אשת עמיתך לא תתן שכבתך לזרע לטמאה בה.** ראוי שתדע שאמרו לזרע איננו תנאי עד שאם לא יוציא זרע לא יתחייב אבל יתחייב כיון שנתן בה שכבתו אף על פי שלא הוציא זרע שכבר נאמר בפרש' כי תצא כי ימצא איש שוכב עם אשה בעולת בעל ומתו גם שניהם ואמנם אמר לזרע להורו' שהשכיבה שאין מדרכה שתהיה לזרע לא יתחייב עליה כאלו תאמר אם הכניס האבר מת והוא באופן שלא יתכן בו הקשי:
@71 **ומזרעך לא תתן להעביר למולך ולא תחלל את שם אלהיך.** כבר התבאר לפי הוראת הגדר כי מולך היתה ע"ז עובדים בה האש והאב נותן מקצת זרעו לכומרי ע"ז ההוא וברשותם יעבירהו ברגליו תוך האש וידמו שבעבודה הזאת כרת ברית עם ע"ז ההיא בתתו מזרעו לה ולזה ידמה שלא היו מעבירים שם כי אם קצת זרע ואחשוב שתהיה הכונה בזאת לעובד מאדים כי הוא אשר ישלוט על הויות האש השורף כמו שנזכר במשפטי הככבים ויתבאר מאד מן החוש ולפי שהוא יורה על המשגל המגונה כשיכונו אל כונה זו זכר בזה המקום כי הוא יזכור אחר זה משכב הזכור והבהמה אשר בתכלית הגנות והנה אפשר שזאת הע"ז היתה מחקות המצריים או הכנענים שזכר ולזה זכרה בזה המקום והוא אפשר עוד שתהיה הכונה בזאת הע"ז שאין שם סבה צוריית אבל הפעולות שנראה לנמצא נמצא הם מצד החום אשר לו עד שתהיה ההזנה מצד החום מזולת נפש כמו שחשבו קצת הקודמים ולזה חשבו שיהיה אלוה מי שהוא התחלת החום אשר בנמצא נמצא ומה שהוא בזה התאר הוא היותר אמתי בחום ולזה היו עובדים אותו והוא מבואר שבעלי זאת האמונה לא יאמינו במציאות הנפש כ"ש שלא יאמינו בהשארותה ולזה לא יגדרו עצמם בכמו אלו הגדרים התוריים אבל ישתדלו בהשגת ההנאות לבד כי אין שם תכלית אחרת לפי זה הדעת ואפשר עוד שזכרו בזה המקום להורות על חוזק גנות אלו העריות שיזכיר עד שהוא מתיחס בגנותו לגנות ע"ז וזה כי כאשר ישכב את זכר שהו' משכב בלתי עושה פרי יורה שהוא לא יתן לא לבו להשיג מה שהיה מן החסד והחנינה במה שנתן השם יתעלה מן הכח בזה הזרע ולזה לא ישתמש בתועלת הנפלא המיוחס לו וכן העניין כמי שיתן שכבתו בבהמה והוא מבואר שמי שמנהגו זה המנהג ר"ל שלא יחקור מה שהיה מן החכמה והסדר והיושר באלו הנמצאות השפלות לא תשלם לו השגה שתהיה בכאן סבה פועלת וצוריית ויבא מפני זה לכמו אלו הדעות הנפסדות עם שהנטיה החזקה להנאות זה החוש בזה האופן תמנעהו מההשתדלות בהשגת שום מושכל ויפול מפני זה ביותר פחות מהדעו' הנפסדות באלו ביארה התורה שלא נקל באלו האזהרות כי המרותנו בהם אפשר שיבא לזאת העברה הנפלאה:
@72 **ואת זכר לא תשכב משכבי אשה תועבה היא.** ר"ל שזה הענין הוא נתעב מצד עצמות:
@73 **ובכל בהמה לא תתן שכבתך לטמאה.** ראוי שתדע שזה הדין שוה בבהמה ובעוף כי הגנות בכלם אחד ואמנם זכר בהמה להיותה יותר קרוב מטבע האדם משאר הב"ח והנה אין הבדל בבהמה בין הגדולה לקטנה שנאמר וכל בהמה וכיון שהערה בה או שהערת בו חייב אם היה גדול כי משכב כולל המשכב אשר כדרך והמשכ' אשר לא כדרך כמו שקדם:
@73 **ואשה לא תעמוד לפני בהמה לרבעה תבל היא.** ר"ל דבר בלי והשחתה להשתמש בכח האנושי להולדה בזה האופן הנפסד שאם היה שתהיה ממנו הולדה לא יהיה הנולד אדם כמו שלא יהיה הנולד מסוס ואתון ולא חמור אבל מין אחר שעם זאת הולדה גם כן תכלה אל מין אחר בלתי מוליד כמו שהתב' בספר ב"ח והוא מבואר שהאדם גדול המעלה מאד ביחס אל הבעלי חיים האחרים ולזה ראוי שיגיע ענש נפלא למי שישתמש במה שהכין הטבע להיות ממנו אדם אל שיהיו ממנו שאר ב"ח:
@74 **אל תטמאו בכל אלה.** ר"ל באי זה שיהיה מאלה כי כן מנהג לשון הקדש אמר וכל דם וכל חלב שור וכבש ועז לא תאכלו והנה ביארה התורה שאלו המעשים המגונים האלו היו סבה לאבדן האמות ההן ולהקיא הארץ יושביה כי לולי רשעת הגוים ההם לא היה מסכים השם יתעלה לאבדן ולגרשן כדי להטיב לישראל כי זה יהיה עול בחק השם יתע' ולפי ששב לכלול בזה הגר שב להזכיר כי גם הגרים בארץ הגיע להם הענש בסבת הפעולות המגונות ולזה אמר כי את כל התעבות האלה עשו אנשי הארץ כי גם הגרים יקראו אנשי הארץ ואמנם תחלה זכר האזרחים במה שאמר כי בכל אלה נטמאו הגוים אשר אני משלח מפניכם כי הגוים אשר בארץ הם האזרחים שהם לגוי אחד ומשפחה אחת כאלו תאמר החתי והאמורי ומה שידמה להם מאלו האמות:
@78 **ולא תקיא אתכם וגו'.** קבלתי בפרוש זה הפסוק מהרב אדוני אבי ז"ל ולא תחשבו שיהיה זה העש המגיע לכם בה שתקיא אתכם כאשר קאה את הגוי אשר לפניכם אבל יתחייבו כרת הנפשות העושות איזה דבר שיהיה מכל התועבות האלה וזהו ההפרש בין העונש שיגיע לכם בזה ובין הענש שהגיע מזה לגוים ההם וכבר יסתפק מספק ויאמר שהו' ראוי שיהי' הענש המגיע מזה לישראל יותר עצום למעלתם כי כל מה שהיה החוטא יותר נכבד היה ראוי שיהיה ענשו יותר חזק וזה הפך מה שיראה מה המאמר ואנחנו אומרים בהתר זה הספק כי אלו האומות התנהגו בכללם באלו הפעולות המגונות ובזולתם ולזה היו ראוים לכמו זה הענש הנפלא ולולי הסתבכם בהם כלם לא הגיע להם זה העונש הכולל ולזה ארך זמנם עם רוע מנהגיהם כמו שאמר כי לא שלם עון האמורי עד הנה ואולם ישראל יענשו אף על פי שלא יחטאו בזה כי אם איש אחד ופעם אחת בשתכרת נפש החוטא ההוא ואמנם שאר האנשים אשר יהיו בקצת עלו המעשים המגונים ע"י ב"ד יתבארו בפרשת קדושים תהיו ושם יתבאר כי כאשר הסתבכו ישראל באלו הפעולות תקיא אותם הארץ אמר ושמרתם את כל חקותי ואת כל משפטי ועשיתם אותם ולא תקיא אתכם הארץ וזה מורה שאם לא ישמרום תקיא אותם הארץ ולזה אחשוב גם כן שתהיה הכונה בזה המקום שישמרו משמרת השם לבלתי עשות מחוקות התועבות האלה כדי שלא תקיא הארץ כאשר קאה את הגוי אשר לפניהם כי זה יקרה להם כשיחטאו בזה רבים מהם והוסיפה התורה להזכיר עונש אחר יקרה לאיש ואיש אשר יחטא בהם והוא הכרת הנפש ההיא ויהיה אמרו כל אשר יעשה וגו'. כאלו יאמר ראוי שתשמרו משמרתי לבלתי חטאו באלו הפעלות המגונות כי כבר יגיע זה העונש לאיש ואיש שיחטא בזה וזכרה תחלה הענש הכולל שיקרה לכלל האומה אם יסתבכו באלו הפעולות ואחר זכר העונש הפרטי שיקרה למי שיחטא בזה היה פרט או כלל ובכאן נשלם ביאור זאת הפרשה:

@1 **ואולם** למה היתה זאת הכפרה בזה האופן הנה ראוי שנאמר בזה לפי מנהגנו והשגתנו ואם יש בזה מן העומק והקושי החזק. ונציע תחלה ונאמר כי מזבח הקטרת מורה על המציאות וההויה וקטרת של בין הערבים מורה על ההפסד כמו שהתבאר בפרשת ואתה תצוה והיו ממנה ארבע קרנות להורות על שההפסד לא יקרה לאדם מצד צורתו אך יקרה לו מצד ההיולי והם היסודות אשר בהמזגם קבל אלו הצורות קצתם באמצעות קצת והנה הקטרת אשר יקטירו עליו מור' על השכל ההיולאני אשר מדרכו שיתעצם במה שיריח האדם מאלו דברים המוחשים רוצה לומר מאופן החכמה אשר ביצירתם כשיופרדו מהם המשיגים ההיולאנים והנה השכל יקח זה המושג מהחוש והדמיון ויפשיטהו ממשיגיו ההיולאנים ובזה האופן ישוב המושכל בכח מושכל בפועל כמו שישים האש מצד הפרדה בקטרת אשר היה מורח בכח מורח בפועל ומזה האופן היו הסמים משל למושכלות כמו שבארנו בפירוש שיר השירים וזה המשל נכפל שם הרבה. והנה המנורה מורה על האופן שיוצא בו השכל ההיולאני מהכח אל הפעל מצד מה שתבין לו הנפש המרגשת והמדמה מהמורגשות כמו שביארנו בפרשת ויקחו לי תרומה ולזאת הסבה המנורה יותר קרובה לקדש הקדשים ממזבח הקטרת ולזאת הסבה היתה בפרכת צורת כרובים להעיר כי מה שבמונרה הוא הערה להשגת השכל ההיולאני שכל בפועל באופן שיהיה במדרגת הכרובים שהם שכלים נבדלים משיגים עצמותם ולזאת הסבה גם כן היתה המנורה מאירה למול קדש הקדשים ששם הכרובים פורשי כנפים למעלה ולפי שההשלמה בזה האופן לשכל היא יותר חזקה בעת המורה על ההפסד וחולשת הכוחות הגופיות והוא עת הזקנה והישישות כמו שנזכר בספר מלחמות יי' הנה העת שנתחנך בו המנור' בערב כמו שביארנו במה שקדם. והנה הכרובי' אשר בקדש הקדשים מורה על השכל הנקנה והשכל הפועל והנה השפע שיקבל השכל הנקנה מהשכל הפועל הגיע בנבואה ולזה היו פניהם איש אל אחיו אל הכפורת אשר על הארון להעיר על אפשרות הגעת הנבואה כי התורה נתנה על יד נביא ואם לא יאמן בנבואה תפול כל התור' וכבר התבאר בספר מלחמו' יי' כי המזגים יתחדשו במורכבות מפני מה שיתחדש מההתמזגות מה שיושפע מהכוכבים באמצעות ניצוציהם לפי מה שנתן להם השם יתע' מהכח ביום הבראם וכמו שיתחדש מההתמזגות כחות הגלגלים אלו המזגים המקבלים כפי כח ככב מהכוכבים ההולכי' ולפי מקומותיו מגלגל המזלות כן יתחדש ממניעיהם שכל הוא נימוס מהשיתחדש מהמזג כחותיה' ובאמצעותו ינתנו הצורו' באלו הדברים ההוים םוהוא השכל הפועל לפי מה שביארנו שם הנה זה מה שראינו להציעו בזה המקום קודם נתינתנו הסבו' במה שנזכר בזאת הפרשה ואחר זאת הצעה נאמר שכבר היה מן ההכרח שיהי' שם מה שיעיר שכבר יכפר השם יתעלה לחוטא כל עונותיו לא השגגות לבד וזה שאם יחשוב האדם שלא יתכפרו לו כמו אלו העונות יהיה מגיע מזה הפסד נפלא וזה שהחוטא מפני האמינו שלא יכפרו לו עונותיו ואם יכבס כתמי חטאיו בנתר התשובה והמעשים טובים הנה נתיאש מן הטוב ולא ישתדל בתקון מעשיו ודעותיו בראותו שכאשר אבד אבד ולזה סבב השם יתע' שיהיה שם יום אחד שיתכפרו בו כל העונות אחר השבר לב החוטא והכנעו בצום ובתשובה ולפי שזה הענין גדול וקשה ראוי שלא ישלם כי אם על יד היותר נבחר כי ליור נכבד יחסו הפעולות היותר גדולות בסוג ההוא ולזאת הסבה בעינה חייב שיהיה זה גם כן בנכבד שבמקומות והנה היתה זאת העבודה בבגדי לבן כי לגנות מה שיכפר עליו באלו העבודות היה בלתי ראוי שישלם הכבוד בזה הקרבן ולזאת הסבה בעינה היה הפר והשעיר נשרפים בזה האופן המגונה חוץ לג' מחנות והיה גם כן מת השעיר המשתלח בתכלית הגנות ובמקום שאין בו הנאה כלל שנאמר אל ארץ גזרה עד הגיע מהגנות בו שלא יוקח דבר ממנו לעבוד בו שום עובדה באופן מהאופנים והנה היה חטאת הכהן פר וחטאת ישראל שעיר לסבה בעינה שהיה חטאת כהן משיח פר וחטאת נשיא שעיר וזה היה לגודל מעלת הכהן כמו שביא' שם עד שהנכבד שבב"ח הוא אצלו בתכלית הפחיתות לחוזק המשכו אל השכל ומאסו ענייני החמר ולפי שכפרת שני השעירים היתה מיוחדת למה שיכפר עליו הפר היה ראוי שיוקחו שניה' יחד לכונה ההיא ולזה לא יתבאר אז אי זה מהם יכפר על הטמאה ואי זה מהם יכפר על כלל העונות ואולם יתברר זה באמצעות נתינת הגורל על יד הכהן הגדול לישב יותר בנפשותינו על שה מכפר על הטמאה וזה מכפר על כלל העונות כאלו היה מוגבל מהשם יתעלה מה שנתברר מפני הגורל כמו שאמ' בחיק יוטל את הגורל ומה' כל משפטו והנה היה המכפר על הטמאה ליי' מה שאין כן במכפר על כל העונות לפי שהעברה אשר בטמאה איננה מצד הענין בעצמו אבל היא כמו שביארנו שהיא להעיר על מציאות הצורה כדי שנעמוד מזה על מציאות השם יתעלה ולזה היה קרב ממנו דבר מה לשם יתעלה מדמו וחלבו ואולם המכפר על כלל העונות לא היה ממנו קרב לשם יתעלה כי אותם העונות מרוחקין מצד עצמותם וכל שכן הזדון בהן שיהיה השעיר ההוא מכפר עליהם והנה יטבול הכהן בכל עת שילבש בגדים להורות שהמכוון מהעבודה כלה שיתנקה מטמאות החמר ומהמרי המיוחס לו ולהורות על חוזק מעלת המכפר הזה בנקיות והנה היו לפי מה שאחשוב שני מיני אלו הטבלות הנזכרות לכונות שונות וזה שהטבילה תהיה בלבשו בגדי לבן הוא להעיר על חוזק טומאת הדבר שיכפר עליו וחלאתו ולזה יצטרך המכפר עליו לתכלית הטהרה כדי שיהיה נכון לטהר כמו זאת הטומאה הנפלאה והטבילה אשר תהיה אחר הפשיטו בגדי לבן הוא להעיר על חוזק טמאת מה שיכפר עליו וחלאתו ולזה כאלו השיגהו דבר מצטרף ליטפל עליו ולזאת הסבה היה שורף הפרים והשעירים הנשרפים טמא. והנה היתה הטבילה במקום קדוש כדי שתשלם העבודה הזאת הנכבדת בזולת יציאת בית המקדש כדי שלא יראה שהניח עניין העבודה ויצא חוץ למקדש וזה ממה שיוסיף כוונה לכהן בענין זאת העבודה והנה אחר שישחט כהן הגדול חטאתו יקטיר קטרת סמים דקה מבית לפרכת כי שם הדברים המורים על השכל שהוא בפועל והוא שכל הנקנה והנה תהיה הקטרת יותר דקה מהקטרת אשר יקטירו על מזבח הזהב לפי שהקטרת ההיא תורה על הכנת השכל היולאני ושכבר תצא אל הפועל וזה אמנם יהיה בהתלמדות וחקירה ואמנם הקטרת אשר יקטיר לפני לפנים מורה על השכל שיצא אל הפעל אבל יעתק מהעדר ההשתמשות בהשגתו אל שישתמש בהשגתו וזה דבר יותר קל מאד מהתלמדות ולהעיר על זה העניין היתה הקטרת ההיא יותר דקה כי אז ימשול בה האש בקלות יותר מהיר ותעלה עשנה בקלות והיתה הקטרת ההוא מלא חפניו כי השכל הנקנה הוא מה שהשיגה ידו במושכלות והיתה הכונה בהקטרת הכהן הגדול זה הקטרת לפני לפנים הוא להורו' שהוא ינהיג עצמו לפי מה שיחייבהו השכל הנקנה הלקוח ממה שיתנו מריחם אלו הדברים המוחשי' אשר בכאן אשר בא מהסידור והיושר ומהפלגת חכמת השם יתעלה והשפעתו הטובות הנפלאות מה שלא יעלם ובזה האופן יתנהג בדרכי השם יתעלה ויהיה זה סבה אל שישמר מהחטאים אשר סבתם הנטיה מהשם יתעלה ולפי שזה השכל ר"ל השכל הנקנה יעלה למעלה אל הנבדלים ויתאחד בזה ובזה האופן תגיע הנבואה אשר תביא ההאמנה בה להאמין בתורה הנה יעמד שם הכהן הגדול עד שיכסה ענן הקטרת אשר הכפרת עליו הם הכרובים כי מזה יעמוד על זאת הכונה ולזה חויב שיהי' בקטרת מעלה עשן כדי שיהיה מוחש עליית זה העשן לזה המקום ושיהיה העשן המורה על השכל הנקנה מורגש עם שזה יתבאר ממנו ששלמות זאת השפעה תהיה גם כן מצד הכח כאשר על הכפרת המעיר על השכל הפו על באמצעות הדברים המוחשי' אשר סמי הקטרת מעירים עליהם כמו שזכרנו במה שקדם והיה זה גם כן אצל התורה שהיתה בארון כי גם היא מישרת אל זאת ההשפעה הישרה נפלאה כמו שביארנו בתחלת זה הספר והנה לא היתה התורה מעכבת זה כי ההישרה אשר היא מצדה על צד היותר טוב לא שתהיה מהסבות ההכרחיות בזאת ההשפעה והנה יזה אחר כן מדם הפר על הכפרת הזאת אחת ולפני הכפרת שבע הזאות להורות כי מחשובתיו ותשוקותיו ופעלותיו המסודרות מגלגל המזלות ושבעה ככבי לכת לפי מקומותיהם מגלגל המזלות אשר בם באופן מה סבה הרבה מהחטאי' והפשעים ואם היה זה במקרה כמו שביארנו בספר מלחמות השם הנה ינהיגם לפי מה שיתנהו השכל השופע מה' ית' אשר הגיעה ממנה התור' וכאלו יתנקה השלם בעל השכל הנקנה מחטאיו בזה האופן ויהיה שכלו נקי מהחטאים אשר חטא ומחלאתם ולזה היתה זאת ההזאה באצבעו הימנית להעיר שיכוין בפעלותיו ודעותיו כלם שיהיו אל הימין לא נוטות ממנו ואח"כ ישחט שעיר החטאת אשר לעם ויזה ממנו בזה האופן בעינו אלא שלא יכפר בו שם כי אם על ענין הטמאה אשר אין המרי בהם מרי מצד עצמותם אלא מצד מה שכהן מההישרה לשכל בדעות האמתיות והיה זה כן כי גדלו עונותיהם מאד ובהם מהרחוק מהשם יתע' זה הקרוב הנפלא ואולם הכהנים למעלתם בעיון ובתורה הנה יהיו חטאיהם מועטי' וקלין ולזה יכפר עליהם יחד הפר בזה המקום הנכבד כי הם אם היה שיחטאו לא יהיה בחטא ההוא מהרחוק מהשם יתעלה הרבה כמו שהוא ראוי בחק השלמים. והנה לא תהיה טענה עלינו בזה אם לא היה שימצאו כהנים בלתי שלמים בזה האופן כי התורה אמנם תדבר בענינים מצד המציאות אשר ראוי שיהיו בו לא מצד הפעל כמו שהצענו בשרשים הכוללים. ואולם המון העם יחטאו הרבה וראוי שיהיה שם מה שיעירם על שאלו החטאים ראוי שירוחקו מאד כדי שישובו מחטאם ויכנע לבבם ולזה ימות השעיר הנושא אלו העונו' בזה האופן המגונה שלא יגיע בו תועלת ובמקום שלא יגיע ממנו תועלת להעיר כי החוטא המחזיק בחטאים ההם לא יהיה במציאותו תועלת כלל ולהורות שאלו העברות יהיו מועטות בכהנים לפי הראוי בהם לא זכרה התורה בביאור ענין הטמאות והחטאים כי אם בישראל. ואמר וכפר על הקדש מטמאות בני ישראל והתודה עליו את כל עונות בני ישראל את כל פשעיהם לכל חטאותם ואמנם בכהנים לא זכר זה אבל אמר וכפר בעדו ובעד ביתו והנה לזאת הסבה ג"כ היה ראוי שיהיה חטאת הכהנים יותר נכבד כי אין להם חטאין באופן מהגנות אשר ימצאו להמון העם ואחר כך יזה כמו שאלו ההזאות על הפרכת ולפני הפרכת מדם הפר תחלה ואחרי כן מדם השעיר לפי שבז' העניין יש הבדל גם כן בין הכהנים והעם וזה כי המקום ההוא מורה על ההשתדלו' במה שיצא בו השכל ההיולאני מהכח אל הפעל ולזה היתה שם המנורה והיו בכפרת הכרובים כמו שביארנו במה שקדם והוא מבואר שכמו שיש הבדל נפלא בין היחידים והממון בשכל הנקנ' כן יש הבדל נפלא ביניהם בהשתדלות בדרכים אשר הם הצעה להגעתו ואולם ההזאות אשר תהיה על מזבח הזהב להיותו מורה על מציאו' השכל ההיולאני והיה מציאות זה השכל שוה באנשים כלם הנה לא תהיה לכהני' לבד ולישר' לבד אבל תהיה להם יחד כשיערבו דם הפר ודם השעיר והנה כשיהיה על קרנות המזבח שהו' מור' על היסודו' שהם סבת ההפסד להעיר שיתנקה זה השכל ההיולאני מטמאת החמר ואח"כ יזו שבע פעמים על שטחו אשר בו יוקטר הקטרת המור' על הכנת זה השכל בהשגה להורו' שזה השכל יתנקה מהמחשבות והתשוקות והפעולות המסודרות לו מהגרמים השמימיים באמצעות החומר שיהיו סבה באופן מה לטעותו בהשגותיו ודעותיו והנה בהזאה הנעשית לפני לפנים ובפרכת שהיא אחת ואחר כן שבעה הערה על זה השכל הפועל שהוא נאצל מן השם יתעלה באמצעות מניע גלגל המזלות ומניעי ככבי לכת כמו שהצענו. והנה לא יהיה אדם באהל מועד בבאו לכפר בקדש כדי שישלם לו ההתבודדו' ויהיה יותר מוכן מפני זה להשיג הסבה אשר בעבורה צותה התורה זה ולזאת הסבה בעינה חוייב שלא יהיה אדם בין האולם והמזבח בבאו לכפר על אהל מועד וראוי שתדע שהשכל ההיולאני נפסד וכן ההשתדלות אל הפעל מאלו הדברים המוחשים כי בהפסד הנפש המרגשת יפסדו כחותיה אשר בהם תעזור אל השכל ההיולאני בהשגתו ולזה לא יהיה אחר המות תוספת שלמו' לשכל הנקנה כי אבדו כליו אשר בהם יוכן לו זה ולזאת הסב' היה במזבח הקטרת ובמנורה מה שיורה על ההויה וההפסד כמו שביארנו בפרשת ואתה תצוה ואמנם השכל הנקנה אינו נפסד כמו שביארנו בספר מלחמות ה' ולזה לא היה בו מה שיורה על ההפסד אבל היתה הקטרתו בבקר לבד שהוא מורה על ההויה כמו שביארנו בפרש' ואתה תצוה ולהעיר של זאת הסבה לא היתה הקטרתו כי אם בבקר היה ראוי שיהיה הסרת הכף והמחתה מקדש הקדשי' בעת הקטרת הקטר' של בין הערבים להעיר אז הכהן המקטיר זה הקטרת על ההבדל שיש בין שני אלו המיני' מהקטרת כי זה לא יוקטר בעת הערב כמו העניין בקטרת אשר יקטירו על מזבח קטרת הסמים ויתעורר מפני זה אל מה שכונה התורה בזה והנה לא היתה הקטרת זה הקטרת המורה על השכל הנקנה כי אם פעם אחת בשנה למעוט המצא זה העניין בשלמות להמון האנשים. ולזה תמצא האנשים שלמי השכל מעטי המספר והנה היתה זאת ההקטר' בחדש השביעי שיכנס בו השמש במזלות הדרומיי' שיש בו רושם אל ההפסד כמו שיתבאר בטבעייות לפי ששלמות זה השכל הוא נמצא יותר עם חולשת כח הגו כמו שביארנו בספר מלחמות ה' ובביאורנו לספר הנפש וכבר היה זה בעשור לחדש להורות על שמספר השכלים הנבדלים הם עשר' והעשירי הוא קודש והוא הש"י והנה היה היום ההוא אסור בהתעסקו' בצרכים הגופיים והמחוייב בענוי נפש כדי שיכנעו יותר ויעשו תשובה כי בה תלוי עניין הכפרה כמו שביארנו ולזאת הסבה היתה התרועה בר"ח הזה כמו שיתבאר במה שיבא ובכאן נשלמה הסבה במה שנוהג ביום הזה מהעבודות ויתר העניינים והוא נפלא מאד ומסכים לענייניהם עד שנעיין זאת העבודה מכל צדדיה יעיר במה שאין ספק בו שהכונה בה הוא מה שזכרה וזה הוא מסגולות האמת ר"ל שהוא מעיד לעצמו מכל צד ומכל פנה:
@1 **והנה** זכר בתחלת סדר עבודת יום הכפורים שהוא הולך במדרגת ההשלמה לענייני הקרבנות והטהרות כמו שהתבאר מדברנו וכבר התבאר מענין העבודה ההיא שהיא היתה במקום מיוחד וע"י איש מיוחד ולא היתה כי אם פעם אחת בשנה וכי זה כלו ממה שיישיר אל שאין בכאן כי אם אלוה אחד ולא לבדו תהיה העבודה ולזה סמך לזה האזהרה מעשיית הקרבנות בזולת המקום המיוחד אף על פי שיעשהו להשם כי זה אולי יביא להאמין רבוי באלהות ולזה תמצא בישראל כשהיו עובדים ע"ז שכבר היתה עבודתה נעשית בכל אחד ממקומותיהם כמ"ש כי מספר עריך היו אלהיך יהודה ולפי שהזביחה שהיתה נהוגה בזמנים ההם לשדי' לא היה בעניינה עבודה אחרת זולת השחיטה שהיתה נעשית לכונה שיתחברו עם השדים ויודיעום העתידות כמו שזכרנו הנה זכר זאת האזהרה אחר הזהרת שחיטת קדשים בחוץ ואחר שזכר זאת הזהיר מהעלאת הקרבנות חוץ לעזרה ואף על פי שיקריבום לשם יתעלה לסבה שזכרנו והוא לישב יותר בלבנו אמונ' הייחוד ואחר כך הזהיר האזהר' מאכילת הדם כי בזה תשלם יותר הכונה אשר בעניין הקרבנות כמו שזכרנו כי בזה יגדל ענינו בעיני האנשים ולזאת הסבה צוה לכסו' דם חיה ועוף עם שבו תועלת להרחיק שלא יזבחו זבחיה' לשעירי' כמו שביארנו ואחר שנשלם לו זה בא להשלי' דין טמאה אחת לא זכרה עם שאר הטמאות והוא טמאת נבלת עוף טהור לפי שענינה נבדל משאר הטמאות וזה שהיא לא תטמא מצד שנעדרה צורתה מפני כי צורתה רחוקה מאד מצורת האדם ולזה לא ינהג בעוף טמאה כמו שינהג בחי ההולך ואמנם תטמא מצד שנעדר ממנו תועלת ההזון לבעלי התורה ולזה לא תטמא אלא בהיותה בבית הבליעה וידמה כי סמך עניינה לענין הדם כי הדם אינו בעצמותו בלתי נאות למזון אבל הוא היותר אמתי במזון כשהיה חלק מהב"ח ואולם יקרה לו שיהיה בלתי נאות למזון מפני קלות הפרד ממנו החלק האוירי והאשיי ולזה יהיה ארציי בעת שיזון האדם ממנו ובלתי נאות להזון ממנו כמו שהתבאר בספר ב"ח הנה אם כן ענין הדם אשר הוא רע הוא מפני טבעו בעת התאכל לא מפני טבעו בעצמותו וסמך עניין העריות לענין הטמאות כי הם גם כן להרחקה מהנטיה מהחסרונות החמר שהוא סבת הטמאה עם שכבר יקרה בהרבה מהם שיעדר מהמשגל ההוא התועלת אשר בעבורו הוכן זה הכח לאדם והוא מבואר במשכב זכור ובמשכב הבהמה וזה יקרה ג"כ הרבה משאר העריות כי אשר ישכב עם שאר בשרי ישתדל לכסות קלונם שלא יהיה מהמשכב ההוא פרי עם שיקרה מזה שאר הפסדים שזכרנו והנה זכר עניין העריות בהדרגה וזה שהוא הקדים ערות אב לערות אם כי יחס הולד לאב יותר חזק מיחסו לאם כי האב נותן מה שהוא במדרגת הפועל להולדה והאם נותנת מה שהיא במדרגת המתפעלת בהולדה כמו שהתבאר בטבעיות ולא אמר אביך הוא לא תגלה ערותו כמו שאמר אמך היא לא תגלה ערותה לפי שאף על פי שלא יהיה אביו היה גלוי ערותו מרוחק ממנו מה שאין כן באמו. ואח"כ זכר ערות אשת אביו אף על פי שאינה אמו כי הוא ערות אביו אלא שהיה בזה העני למטה מערות אמו ומערות אביו וזה מבואר בנפשו כי אין אשת הקרוב קרוב בקרובתו ואחר שזכר מה שיתרחק ממנו מההורי' זכר ערו' האחות איך שתהיה אחותו כי היא שאר בשרו והמשיך לה הרחקת הבעילה לנולדים ממנו שהם בשר מבשרו כמו בת בנו ובת בתו כי הם מאוחרים בזמן ולזה זכרם בסוף ושתקה התורה מבתו כאלו תאמר כי לגודל הגנות בזה אצל כל האנשים לא תצטרך התורה להזכיר זה ואחר זה זכר ערות האחות מצד מה שהיא בת אשת אב עם היותה אחות כי מצד היותה אחות כבר קדמה האזהרה בה ואולם עתה יוסיף להזהיר בה כשקרה עם זה שתהי' בת אשת האב ומזה הצד שהיא למטה מאד מכל מה שקדם באלו העריות ואחר שהשלים המאמר בערות האחות שהיא שארו זכר הערוה שתהיה בשאר האב והאם כי השארו יותר קרוב משאר ההורים וזכר תחלה שאר האב לסבה בעינה שזכר תחלה ערות האב וראוי לעיין למה מנעה ערות אב ואחי האב ולא מנעה שאר הזרים שהם שאר בשר בזולת הצווי הכולל במשכב זכור. ואח"כ זכר ערו' אחי האב כי הוא כמו בשר אחד עם ערות האב ואחר שהזכיר עניינו להיות המשגל ההו' זר מאד רוצה לומר משכב זכור ולפי שזכר ענינו השלים המאמר בערות אשתו שהוא למטה ממנו בקרבה ולמטה מאחות אב ואחות אם ואחר שזכר ערות מה שימשך מההורים משאר בשר ומצד האישות אשר לשאר הבשר בא להשלים מה שימשך מצד האישות לשאר הקרובים והוא ראוי שיקדים אשת אחיו לאשת בנו לפי הסדור הקודם ואמנם זכר תחלה אשת בנו לפי שאשת אחיו תהיה בקצת העתי' מותרת והו' כשמת בלא ולד כמו שיתבא' בפרשת יבמה ולזה הקדימה התורה ערות אשת הבן לערות אשת האח ואחר שזכרה העריות הנאסרות לו מצדו זכר העריות הנאסרות לו מפני היותם שאר אשת כי הם בזה העניין למטה מהעריות שהם שארו ושאר הוריו והקדים לזכור מה שהיה משאר אשתו שאין בו התר לעולם ואחר זכר ערות אחות אשתו כי היא תהיה מותר' לו לאחר מיתתה ואחר כך זכר ערות הנדה וערות אשת איש כי הן דומו' בזה הענין לערות אחות אשה וזה שכמו שערות אחות אשה אינה אסורה אלא בעת היותה אחות האשה וזה יהיה בחיי אשתו כי אחר מיתתו אינה אחות אשתו כן ערות הנדה לא תהיה אסורה אלא בעת היות טומאתה בה וערות אשת איש לא תהיה אסורה אלא בעת היות ואשת איש והנה זכרה התורה ערות אשת איש בסוף אלא העריות לפי שכבר היה מפורסם גם בשמנים ההם גנות הבא על אשת איש ולזה אמר אברהם על אשתו שהיא אחותו כדי שלא ימיתוהו למען ישכבו אחד זה עם אשתו וכאלו ביאר' התורה בזה שאלו העריות הם יותר מגונות מערות אשת איש עם היותה בתכלית הגנות למה שיגיע מזה בענייני' האנושיים כי האדם כשלא ידע שאשר תלד אשתו הוא בנו לא ישתדל במוסרו ובתקו' הנהגתו ויהיה זה סבה להבצר השלמו' מהנולדים כי יצר לב האדם רע מנעוריו ואולם בעניינים המדיניים הוא מבואר כי זה יהיה סבה להריגת האנשים קצתם קצת ברצות האחד לקחת אשת חבירו בחזקה עם שזה יהיה סבה אל שלא תהיה בכאן משפחה כי לא יהיה יודע האדם אי זה הוא אביו ואי זהו בנו ואיזה אחיו והנה התועלת בענין המשפחה בדברים המדיניים הוא במואר והנה זכר אחר זה עניין המולך וערות הזכר וערות הבהמה לסבה שזכרנו בביאורנו בזה במקום:
@1 **ואחר** שנשלם לנו הסדור בזה הענין ראוי שנעיין בהתר ספר אחד יסופק במה שנזכר מהעריות בזה שכבר זכרה התורה בעריות הזכור ערות אביו ואחי האם לא זולתם מהזכרים שהם שאר בשר כמו האח והבן והנה לא זכרה התורה גם כן ערות אחי אם ואשת אחי אם כמו שזכרה ערו' אחי האב ואשת אחי האב והנה יראה שכבר היה ראוי שיהיה היחס בזה אחד כי הוא שאר האם ונאמר כי העזות יותר נפלא כשיבעל ענף השרש ממה שהוא כשבעל הענף הענף או כשיבעל השר' ההענף והוא מבואר בנפשו וכ"ש כשהיה השרש מי שהוא השרש האמתי בהולדה והוא האב שהוא השרש הפועל בהולדה ולזה היה יותר חזק הגנות כשיבעלהו הבן מגנות בעילת האח והבן וזה שהבעילה יש בה שררה מה לבועל על הנבעל ומי שישתרר על אדוניו הוא יותר חזק הגנות מהשתרר על בני גילו אל על מצרפו ועוד שהוא ישים בזה הפעל אותו מתפעל ממנו וזה בתכלי' הגנות ולהעיר שיחס הבן לאב יותר חזק מיחסו לאם כמו שיתבא' בטבעיות היתה ערות אשת אב אסורה מצד מה שהיא אשת אב ולזה לא היתה ערות בעל אמו ואסורה מצד מה שהוא בעל אמו אבל תאסר עליו לבד מצד היותו זכר ולזאת הסבה ג"כ נאסרה ער'ות אחי האב כי הוא כמו בשר אחד עם האב ולא נאסרה ערות אחי האם כדי שנתעורר מפני זה אל שהמבוא אשר בהולדה לאב ולאם הוא יותרק אמתי לאב ממה שהוא לאם ומזה המקום יתבאר שלא נסר מהזכרים מפני שאר בשר כי אם האב ואחי האב שאם היתה כונת התורה שינהג זה האור בכל הזכרים שהם שאר בשר היה ראוי שתזכור זה בזכרים אשר זה הדין ראוי שיהיה בהם יותר חלוש לא הזכרים שזה הדין ראוי שיהיה בהן יותר חזק וכבר נשלמה הסבה בסדור מה שנזכר בזאת הפרשה וראוי שתדע שענייני זאת הפרשה כולם השתתפו בשיש בהם חיוב כרת או יתלה בהם מה שיתחייבו בו כרת וזה שענוי יום הכפורים והשביתה בו ממלאכה ושחיטת הקדשים בחוץ והעלאתם בחוץ ואכילת הדם יתחייבו בהם כרת וכסוי הדם בחיה ובעוף הוא לשמירת שלא יאכל הדם שיש בו חיוב כרת כמו שנזכר שם וטמאת נבלת עוף טהור יתלה בה מי שיתחייבו בו כרת אם לא יטהר ממנ' כמו שאמר ואם לא יכבס ובשרו לא ירחץ ונשא עונו וכן הקריבה אל העריות לגלות ערוה נתלה בו' מה שיתחייבו בו כרת והוא גלוי ערוה וכן גלוי העריות וההעברה למולך יש בהם חיוב כרת כמו שנזכר בזאת הפרשה ואולם התועלו' המגיעו' מזאת הפרשה הם תשעה:
@1 **התועלת** הראשון הוא במצות והוא האזהרה מלבא לפני לפנים שלא לצורך עבודה ותועלת זאת ההזהרה מבואר כי מה שיורגל האדם בראייתו לא יפליג לחקור על עניינו ולתת ללבו למה היה זה כן בזה האופן לחשבו שכבר אפשר לו לראותו תמיד כמו הענין שיפליג במה שלא יראה אותו כי אם לעתים רחוקים ולזה יהיה זה סבה לעמוד על סוד הענין ההוא אשר כונה בו התורה על מה שלא יותר לו לאדם לראותו בכל עת שירצה כי אם פעם אחת בשנה ועם כמו זאת העבודה הנפלאה תגדל מעלתו מאד בנפש ויהיה זה סבה שיתבונן בענינו ויחקור על סודו ובזה יגיע התועלת אשר כונה התורה בו וכבר יתבאר לך מעוט הבנת האדם בדבר המורגל שאתה תראה באלו התפלות הנפלאות אשר סדרו' לנו אנשי כנסת הגדולה שלרוב הרגילנו בהם נדבר בהם תמיד ולא נשתדל לעמוד על סודם שיהיה זה סבה לרבים מחכמנו שיטעו בהם הרבה בדבר' בהם למעוט עמידתם על המכוון בהם וכן תמצא בתורתנו השלמה שלרוב הרגילנו בזה הסתפקנו בקריאתה לבד ולא נעמיק לעמוד על כוונתה עד שאין לרבים מבקיאי חכמינו שום ציור מהרבה מענייניה כמו מלאכת המשכן וכליו ועניין הקרבנות והטמאות והטהרות ומה שידמה להם ומכלל זאת האזהרה גם כן שלא יכנס אדם לאהל מועד שלא לצורך עבודה לזאת הסבה בעינה אלא שיתחייבו על זה מיתה כמו העניין במי שנכנס לפני לפנים שלא לצורך עבודה כמו שביארנו בביאורנו לזאת האזהרה מהמקומות הכוללים:
@1 **התועלת** הב' הוא במצות גם כן והוא הצווי בעבודת יום הכפורים וכבר ביארנו התועלת המגיע מזאת המצוה:
@1 **התועלת** הג' הוא במצות והוא הצווי להתענות ביום הכפורים ולשבות בו מכל מלאכה וכבר נתבאר התועלת המגיע מאלו המצות:
@1 **התועלת** הד' הוא במצות והוא שהוזהרנו מלשחוט הקרבנות חוץ לעזרה ולהקריב חוץ לעזרה וכבר ביארנו במה שקדם התועלת המגיע מאלו האזהרות:
@1 **התועלת** הה' הוא במצות והוא מה שצונו לכסות דם חיה ועוף הראויים לאכילה כבר ביארנו התועלת המגיע מזאת המצוה:
@1 **התועלת** הו' הוא במצות הוא לדין בנבלת עוף טהור בטומאתה שלה באופן שצותה התורה וכבר נתבאר התועלת המגיע בזאת המצוה בסוף פרשת ויהי ביום השמיני ובביאורנו לזאת הפרשה:
@1 **התועלת** הז' הוא במצות והוא האזהרה שלא נקרב לשאר בשר ושלא נגלה ערוה מאלו העריות שזכרה התורה או שהם בכח הבריה וכבר נתבאר התועלת המגיע מאלו האזהרות בביאורנו לזאת הפרשה ולפרשת אשה כי תזריע:
@1 **התועלת** הח' הוא במצות והוא האזהרה שהוזהרנו מלהעביר מזרענו למולך והתועלת בזאת האזהרה הוא נפלא מאד כי הטעות בהתחלה הראשונה הוא השם יתעלה מונע כל שלמות האנושי וכ"ש כשהיה התעות בו בזה האופן אשר לא תתכן עמו שום חכמה ושום ידיעה וזה כי כשלא נודה שתהיה בכאן סבה פועלת היא שכל תסור מהדברים הסבה התכליתית והצוריית שהם הנכבדות שבסבות וזה מבואר מאד:
@1 **התועלת** הט' הוא בדיעות והוא שכאשר יביא ההכרח להביא הרע על קצת האנשים להשגחה על הטובים הנה לא יסכים השם להביא הרע על האנשים ההם אם לא היו ראויים לו וזה ראוי בחק היושר האלהי וחוזק חנינתו לנמצאות עד שלא יביא רע ממנו כי אם מצד מה שהוא טוב ולזה ביאר כי הורשת ה' יתע' הגוים ההם מפני ישראל היתה מצד הפלגת רוע מעשיהם ובזאת הסבה הקיאה הארץ אותם ובזה המאמר עם זה הערה לחוזק הארץ ההיא אל שישפע בה השפע האלהי עד שלמעלתה לא תוכל להכיל כמו אלו הפעולות המגונות וזה שהוא מבואר כי המקומות היותר נכבדים ראוי שתנהגו בהם בקדושה נוספת:
